function normalizeAppLang(lang) {
  const clean = String(lang || '').trim().toLowerCase().split('-')[0];
  if (['en', 'tl', 'ko', 'vi', 'ar', 'tr', 'hi', 'id', 'ms', 'pt', 'es', 'ru'].indexOf(clean) !== -1) return clean;
  return 'en';
}
window.normalizeAppLang = normalizeAppLang;

function tLang(lang, bnText, enText, arText) {
  const l = normalizeAppLang(lang);
  if (l === 'ar') return arText !== undefined ? arText : enText;
  if (l !== 'en' && enText && window.aloI18n && typeof window.aloI18n.translateText === 'function') {
    return window.aloI18n.translateText(enText, l);
  }
  return enText;
}
window.tLang = tLang;

// ==========================================
// SUPABASE & CLOUD DATABASE INTEGRATION (USER, TEAM, TRANSACTIONS)
// ==========================================
function isBangladeshPhoneDigits(phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  if (!digits) return false;
  return /^(?:880|0)?1[3-9]\d{8}$/.test(digits);
}

function mapSupabaseUser(d) {
  if (!d) return null;
  let opt = {};
  if (d.bkash_optional) {
    try { opt = typeof d.bkash_optional === 'string' ? JSON.parse(d.bkash_optional) : d.bkash_optional; } catch(e) { opt = {}; }
  }
  if (!opt || typeof opt !== 'object') opt = {};

  const nName = d.nagad_name || opt.nagad_name || '';
  const nPhone = d.nagad_phone || opt.nagad_phone || '';
  const uName = d.usdt_name || opt.usdt_name || '';
  const uAddr = d.usdt_address || opt.usdt_address || '';
  const purchasedPackages = Array.isArray(opt.purchased_packages) && opt.purchased_packages.length > 0
    ? opt.purchased_packages
    : [d.package_level || d.packageLevel || 'LV0'];
  if (!purchasedPackages.includes('LV0')) purchasedPackages.unshift('LV0');

  const isManualLang = Boolean(opt.language_manual);
  const mappedLang = isManualLang ? normalizeAppLang(opt.language || 'en') : 'en';
  const defaultNameForLang = tLang(mappedLang, 'সদস্য', 'Member', 'عضو');
  const rawName = String(d.name || '').trim();
  const isDefaultPlaceholder = !rawName || rawName === 'সদস্য' || rawName === 'Member' || rawName === 'عضو' || rawName === 'सदस्य';

  return {
    phone: d.phone || d.account_number || d.accountNumber,
    accountNumber: d.account_number || d.accountNumber || d.phone,
    name: opt.real_name || (isDefaultPlaceholder ? defaultNameForLang : rawName),
    realName: opt.real_name || (!isDefaultPlaceholder ? rawName : ''),
    fundPassword: opt.fund_password || '',
    fundPasswordLocked: Boolean(opt.fund_password),
    passwordHash: d.password_hash || d.passwordHash || '',
    plainPassword: d.plain_password || d.plainPassword || '',
    memberId: d.member_id || d.memberId || ('AL' + Date.now().toString().slice(-8)),
    inviteCode: d.invite_code || d.inviteCode || '',
    superiorId: d.superior_id || d.superiorId || '11',
    superiorPhone: opt.superior_phone || d.superior_phone || d.superiorPhone || '',
    packageLevel: d.package_level || d.packageLevel || 'LV0',
    purchasedPackages: purchasedPackages,
    packagePurchaseDates: (opt.package_purchase_dates && typeof opt.package_purchase_dates === 'object') ? Object.assign({}, opt.package_purchase_dates) : {},
    balance: typeof d.balance === 'number' ? d.balance : parseFloat(d.balance || 0) || 0,
    frozenBalance: Number(opt.frozen_balance) || 0,
    lv0FrozenBalance: Number(opt.lv0_frozen_balance) || 0,
    adminUnfrozenBalance: Number(opt.admin_unfrozen_balance) || 0,
    rechargeFrozenBalance: opt.recharge_frozen_balance !== undefined ? (Number(opt.recharge_frozen_balance) || 0) : null,
    lifetimeEarnings: Number(opt.lifetime_earnings) || 0,
    todayIncome: Number(opt.today_income) || 0,
    totalIncome: Number(opt.total_income) || 0,
    completedMissions: Number(opt.completed_missions) || 0,
    lv0CompletedTasks: Number(opt.lv0_completed_tasks) || 0,
    rechargeAmount: Number(opt.recharge_amount) || 0,
    cashoutAmount: Number(opt.cashout_amount) || 0,
    acceptedMissions: Array.isArray(opt.accepted_missions) ? opt.accepted_missions : [],
    savingsPlan: opt.savings_plan || null,
    claimedInviteRewards: Array.isArray(opt.claimed_rewards) ? opt.claimed_rewards : [],
    claimedUsdtOnchain: Number(opt.claimed_usdt_onchain) || 0,
    usedSpins: Number(opt.used_spins) || 0,
    bonusSpins: Number(opt.bonus_spins) || 0,
    spinHistory: Array.isArray(opt.spin_history) ? opt.spin_history : [],
    country: (function() {
      const rawOptCountry = String(opt.country || '').trim().toUpperCase();
      const rawDial = String(opt.dial_code || '').trim();
      const phoneRaw = String(d.phone || d.account_number || d.accountNumber || '').trim();
      const looksLikeBdPhone = isBangladeshPhoneDigits(phoneRaw);

      // Auto-heal Bangladesh accounts previously overwritten to 'US' when USD became global
      if ((rawOptCountry === 'US' || !rawOptCountry) && (rawDial === '+880' || (rawDial !== '+1' && looksLikeBdPhone))) {
        return 'BD';
      }
      if (rawOptCountry) {
        return rawOptCountry;
      }
      if (rawDial === '+880') {
        return 'BD';
      }
      const dialMatch = rawDial && typeof COUNTRY_DATABASE !== 'undefined'
        ? COUNTRY_DATABASE.find(function(c) { return c.dialCode === rawDial; })
        : null;
      if (dialMatch && dialMatch.code) {
        return String(dialMatch.code).toUpperCase();
      }
      if (looksLikeBdPhone) {
        return 'BD';
      }
      if (opt.currency === 'INR' || (phoneRaw.startsWith('91') && phoneRaw.length >= 12)) {
        return 'IN';
      }
      return 'BD';
    })(),
    currency: 'USD',
    dialCode: (function() {
      const rawOptCountry = String(opt.country || '').trim().toUpperCase();
      const rawDial = String(opt.dial_code || '').trim();
      const phoneRaw = String(d.phone || d.account_number || d.accountNumber || '').trim();
      if ((rawOptCountry === 'BD' || rawOptCountry === 'US' || !rawOptCountry) && (rawDial === '+880' || (rawDial !== '+1' && isBangladeshPhoneDigits(phoneRaw)))) {
        return '+880';
      }
      return rawDial || '';
    })(),
    commissionDust: Number(opt.commission_dust) || 0,
    language: mappedLang,
    languageManual: isManualLang,
    bkashName: d.bkash_name || d.bkashName || '',
    bkashPhone: d.bkash_phone || d.bkashPhone || '',
    bkash: {
      fullName: d.bkash_name || d.bkashName || '',
      phone: d.bkash_phone || d.bkashPhone || ''
    },
    nagadName: nName,
    nagadPhone: nPhone,
    nagad: {
      fullName: nName,
      phone: nPhone
    },
    usdtName: uName,
    usdtAddress: uAddr,
    usdt: {
      fullName: uName,
      address: uAddr,
      network: 'BEP20'
    },
    accountStatus: opt.account_status || 'active',
    _rawOpt: opt,
    createdAt: d.created_at || d.createdAt || opt.created_at || '',
    updatedAt: d.updated_at || d.updatedAt || opt.updated_at || ''
  };
}

function resetTeamAndCommissionDom() {
  try {
    const zeroTextIds = ['invite-team-members-count', 'invite-today-new-count', 'salary-active-a-count', 'team-stat-first-charge', 'team-stat-direct-push', 'team-stat-total-size', 'team-stat-new-members', 'tier-metric-members', 'lucky-spin-draws-num', 'lucky-spin-qualified-count', 'lucky-spin-today-count'];
    zeroTextIds.forEach(function(id) {
      const el = document.getElementById(id);
      if (el) el.textContent = '0';
    });
    const zeroMoneyIds = ['invite-total-commission', 'invite-today-commission', 'team-stat-balance', 'team-stat-flow', 'team-stat-recharge', 'team-stat-cashout', 'tier-metric-recharge', 'tier-metric-rebate'];
    zeroMoneyIds.forEach(function(id) {
      const el = document.getElementById(id);
      if (el) el.textContent = '0.00';
    });
    const teamAccordion = document.getElementById('team-fresh-accordion-container');
    if (teamAccordion) teamAccordion.innerHTML = '';
    const spinHistoryList = document.getElementById('lucky-spin-history-list');
    if (spinHistoryList) spinHistoryList.innerHTML = '';
    document.querySelectorAll('.salary-row').forEach(function(row) {
      row.classList.remove('done');
      const fillEl = row.querySelector('.fill');
      if (fillEl) fillEl.style.width = '0%';
      const pctEl = row.querySelector('.pct');
      if (pctEl) pctEl.textContent = '0%';
      const ratioEl = row.querySelector('.salary-count-ratio');
      if (ratioEl) ratioEl.textContent = '';
    });
    document.querySelectorAll('.salary-pay, .invite-claim-btn').forEach(function(btn) {
      btn.dataset.currentCount = '0';
      btn.dataset.isClaimed = 'false';
      btn.dataset.isUnlocked = 'false';
    });
  } catch (e) {}
}

function clearUserCachesOnAuthSwitch() {
  try {
    const keys = [
      'alo_real_name',
      'alo_fund_password',
      'alo_fund_password_locked',
      'alo_bkash_account',
      'alo_nagad_account',
      'alo_usdt_account',
      'alo_usdt_address',
      'alo_claimed_invite_rewards',
      'withdrawal_history_records',
      'my_pass_available_bal',
      'aloAcceptedMissions',
      'alo_usdt_deposits_history',
      'aloTeamRecords'
    ];
    keys.forEach(function(k) { localStorage.removeItem(k); });
  } catch (e) {}
  try {
    if (typeof _realTeamCache !== 'undefined') _realTeamCache.clear();
    if (typeof _realTeamInFlight !== 'undefined') _realTeamInFlight.clear();
    if (typeof cachedTeamReportData !== 'undefined') cachedTeamReportData = null;
    if (typeof cachedTeamCommissionTxs !== 'undefined') cachedTeamCommissionTxs = null;
    if (typeof expandedTeamTiers !== 'undefined') expandedTeamTiers = { 1: true, 2: false, 3: false };
  } catch (e) {}
  resetTeamAndCommissionDom();
}

function hydrateUserCachesFromCloud(user) {
  if (!user) return;
  try {
    const normPhone = normalizeBdPhone(user.phone || user.accountNumber || '');
    const boundRealName = user.realName || (user.name && user.name !== 'সদস্য' && user.name !== 'Member' && user.name !== 'عضو' && user.name !== 'सदस्य' ? user.name : '');
    if (boundRealName) {
      localStorage.setItem('alo_real_name', boundRealName);
      user.realName = boundRealName;
    } else {
      localStorage.removeItem('alo_real_name');
    }

    if (user.fundPassword) {
      localStorage.setItem('alo_fund_password', String(user.fundPassword));
      localStorage.setItem('alo_fund_password_locked', 'true');
    } else {
      localStorage.removeItem('alo_fund_password');
      localStorage.removeItem('alo_fund_password_locked');
    }

    const bkPhone = (user.bkash && user.bkash.phone) || user.bkashPhone || '';
    if (bkPhone) {
      const bkData = {
        fullName: (user.bkash && user.bkash.fullName) || user.bkashName || boundRealName || '',
        phone: bkPhone,
        locked: true,
        updatedAt: user.updatedAt || new Date().toISOString()
      };
      localStorage.setItem('alo_bkash_account', JSON.stringify(bkData));
      user.bkash = bkData;
    } else {
      localStorage.removeItem('alo_bkash_account');
    }

    const ngPhone = (user.nagad && user.nagad.phone) || user.nagadPhone || '';
    if (ngPhone) {
      const ngData = {
        fullName: (user.nagad && user.nagad.fullName) || user.nagadName || boundRealName || '',
        phone: ngPhone,
        locked: true,
        updatedAt: user.updatedAt || new Date().toISOString()
      };
      localStorage.setItem('alo_nagad_account', JSON.stringify(ngData));
      user.nagad = ngData;
    } else {
      localStorage.removeItem('alo_nagad_account');
    }

    const usAddr = (user.usdt && user.usdt.address) || user.usdtAddress || '';
    if (usAddr) {
      const usData = {
        fullName: (user.usdt && user.usdt.fullName) || user.usdtName || boundRealName || '',
        address: usAddr,
        network: 'BEP20',
        locked: true,
        updatedAt: user.updatedAt || new Date().toISOString()
      };
      localStorage.setItem('alo_usdt_account', JSON.stringify(usData));
      localStorage.setItem('alo_usdt_address', usAddr);
      user.usdt = usData;
    } else {
      localStorage.removeItem('alo_usdt_account');
      localStorage.removeItem('alo_usdt_address');
    }

    if (Array.isArray(user.claimedInviteRewards)) {
      localStorage.setItem('alo_claimed_invite_rewards', JSON.stringify(user.claimedInviteRewards));
    }

    if (Array.isArray(user.acceptedMissions)) {
      // Merge cloud missions with same-user local missions so Completed tasks and active screenshots are never lost
      let localList = [];
      try { localList = JSON.parse(localStorage.getItem('aloAcceptedMissions') || '[]'); } catch(e) {}
      const sameUserLocal = Array.isArray(localList)
        ? localList.filter(function(lm) {
            return lm && lm.id && (!lm.userPhone || !normPhone || normalizeBdPhone(lm.userPhone) === normPhone);
          })
        : [];
      const mergedMissions = typeof mergeMissionLists === 'function'
        ? mergeMissionLists(user.acceptedMissions, sameUserLocal)
        : user.acceptedMissions;
      if (typeof writeMissionsToLocalStorageSafe === 'function') {
        writeMissionsToLocalStorageSafe(mergedMissions);
      } else {
        localStorage.setItem('aloAcceptedMissions', JSON.stringify(mergedMissions));
      }
      user.acceptedMissions = mergedMissions;
    }

    if (user.savingsPlan && normPhone) {
      localStorage.setItem('aloSavingsPlan_' + normPhone, JSON.stringify(user.savingsPlan));
    }

    if (typeof user.balance === 'number') {
      localStorage.setItem('my_pass_available_bal', user.balance.toFixed(2));
    }
  } catch (e) {}
}

window.saveUser = function(u) {
  if (!u) return;
  try {
    localStorage.setItem('aloSignedInUser', JSON.stringify(u));
    if (typeof u.balance === 'number') {
      localStorage.setItem('my_pass_available_bal', u.balance.toFixed(2));
    }
  } catch (e) {}
  if (typeof dbSaveUser === 'function') {
    dbSaveUser(u).catch(function() {});
  }
};

