let currentRegistrationCountry = COUNTRY_DATABASE[0]; // Default Bangladesh
let currentLoginCountry = COUNTRY_DATABASE[0];        // Default Bangladesh
let currentCountryPickerMode = 'register';            // 'login' | 'register'

function getCountryDisplayName(item, langOverride) {
  if (!item) return '';
  const currentLang = normalizeAppLang(langOverride || (window.aloI18n ? window.aloI18n.getLanguage() : '') || localStorage.getItem('alo_lang') || 'en');
  if (currentLang === 'bn') return item.nameBn || item.nameEn;
  if (currentLang === 'ar') return item.nameAr || item.nameEn;
  return item.nameEn;
}

function getCountryFlagUrl(isoCode, size) {
  const lower = String(isoCode || 'bd').trim().toLowerCase();
  return `https://flagcdn.com/w${size || 40}/${lower}.png`;
}

function syncCountryTriggerUi(mode, country, langOverride) {
  if (!country) return;
  const prefix = mode === 'login' ? 'login' : 'register';
  const displayName = getCountryDisplayName(country, langOverride);
  const flagImg = document.getElementById(`${prefix}-country-flag-img`);
  const flagFallback = document.getElementById(`${prefix}-country-flag-fallback`);
  const nameEl = document.getElementById(`${prefix}-country-name-display`);
  const codeEl = document.getElementById(`${prefix}-country-code-display`);

  if (flagImg) {
    flagImg.src = getCountryFlagUrl(country.code, 40);
    flagImg.srcset = `${getCountryFlagUrl(country.code, 80)} 2x`;
    flagImg.alt = country.nameEn || '';
    flagImg.style.display = '';
  }
  if (flagFallback) {
    flagFallback.textContent = country.flag || '🌐';
    flagFallback.style.display = 'none';
  }
  if (nameEl) {
    nameEl.textContent = displayName;
  }
  if (codeEl) {
    codeEl.textContent = country.dialCode;
  }
}

function getCountryByCode(code) {
  if (!code) return COUNTRY_DATABASE[0];
  const clean = String(code).trim();
  const lower = clean.toLowerCase();
  const upper = clean.toUpperCase();
  const digits = clean.replace(/\D/g, '');

  // Priority 1: exact ISO code match (prevents +1 / +7 / +358 ambiguity)
  const exactIso = COUNTRY_DATABASE.find(function(c) { return c.code === upper; });
  if (exactIso) return exactIso;

  // Priority 2: exact dial code or name match
  return COUNTRY_DATABASE.find(function(c) {
    if (c.dialCode === clean) return true;
    if (digits && c.dialCode.replace(/\D/g, '') === digits) return true;
    if (c.nameBn === clean || c.nameBn.toLowerCase() === lower) return true;
    if (c.nameEn.toLowerCase() === lower) return true;
    if (c.nameAr && (c.nameAr === clean || c.nameAr.toLowerCase() === lower)) return true;
    if (lower === 'egypt' || lower === 'মিশর' || lower === 'مصر' || lower === 'eg') return c.code === 'EG';
    if (lower === 'india' || lower === 'ইন্ডিয়া' || lower === 'ভারত' || lower === 'ind' || lower === 'in') return c.code === 'IN';
    if (lower === 'bangladesh' || lower === 'বাংলাদেশ' || lower === 'bd') return c.code === 'BD';
    if (lower === 'usa' || lower === 'united states' || lower === 'united states of america') return c.code === 'US';
    if (lower === 'uk' || lower === 'united kingdom') return c.code === 'GB';
    if (lower === 'uae' || lower === 'united arab emirates') return c.code === 'AE';
    return false;
  }) || COUNTRY_DATABASE[0];
}

function populateAllCountrySelects(langOverride) {
  const currentLang = normalizeAppLang(langOverride || (window.aloI18n ? window.aloI18n.getLanguage() : '') || localStorage.getItem('alo_lang') || 'en');
  const buildOptions = function(selectedVal, bgClass) {
    return COUNTRY_DATABASE.map(function(item) {
      const displayName = getCountryDisplayName(item, currentLang);
      const selAttr = item.code === selectedVal ? ' selected' : '';
      return `<option value="${item.code}" class="${bgClass} text-white"${selAttr}>${item.flag} ${displayName} (${item.dialCode})</option>`;
    }).join('');
  };

  const loginSelect = document.getElementById('login-country-select');
  if (loginSelect) {
    const prevLogin = loginSelect.value || (currentLoginCountry && currentLoginCountry.code) || 'BD';
    const resolvedLogin = getCountryByCode(prevLogin);
    currentLoginCountry = resolvedLogin;
    loginSelect.innerHTML = buildOptions(resolvedLogin.code, 'bg-[#141e3c]');
    loginSelect.value = resolvedLogin.code;
  }
  syncCountryTriggerUi('login', currentLoginCountry, currentLang);

  const regSelect = document.getElementById('register-country-select');
  if (regSelect) {
    const prevReg = regSelect.value || (currentRegistrationCountry && currentRegistrationCountry.code) || 'BD';
    const resolvedReg = getCountryByCode(prevReg);
    currentRegistrationCountry = resolvedReg;
    regSelect.innerHTML = buildOptions(resolvedReg.code, 'bg-[#07173d]');
    regSelect.value = resolvedReg.code;
  }
  syncCountryTriggerUi('register', currentRegistrationCountry, currentLang);
}
window.populateAllCountrySelects = populateAllCountrySelects;

function selectRegistrationCountry(code) {
  const country = getCountryByCode(code);
  if (!country) return;
  currentRegistrationCountry = country;

  // 1. Update hidden native dropdown & visible trigger button
  const selectEl = document.getElementById('register-country-select');
  if (selectEl && selectEl.value !== country.code) {
    selectEl.value = country.code;
  }
  syncCountryTriggerUi('register', country);

  // 2. Update Hidden Form Data
  const codeInput = document.getElementById('register-country-code');
  if (codeInput) codeInput.value = country.code;
  const nameInput = document.getElementById('register-country-name');
  if (nameInput) nameInput.value = country.nameEn;
  const currCodeInput = document.getElementById('register-currency-code');
  if (currCodeInput) currCodeInput.value = country.currency;
  const currSymInput = document.getElementById('register-currency-symbol');
  if (currSymInput) currSymInput.value = country.symbol;
  const currNameInput = document.getElementById('register-currency-name');
  if (currNameInput) currNameInput.value = country.currencyName;
  const dialCodeInput = document.getElementById('register-dial-code');
  if (dialCodeInput) dialCodeInput.value = country.dialCode;

  // 3. Update Phone Prefix with numerical dial code!
  const prefixEl = document.getElementById('register-phone-prefix');
  if (prefixEl) {
    prefixEl.innerHTML = `${country.dialCode} <span class="phone-register-prefix-arrow text-[10px]" aria-hidden="true">▼</span>`;
    prefixEl.setAttribute('aria-label', `Country: ${country.nameEn}, Dial Code: ${country.dialCode}`);
  }
  const phoneInput = document.getElementById('register-phone');
  if (phoneInput) {
    const rule = typeof getCountryPhoneRule === 'function' ? getCountryPhoneRule(country.code) : { max: country.phoneLen || 15, trunkZero: true };
    phoneInput.maxLength = Math.max(15, rule.max + 5);
    phoneInput.setCustomValidity('');
  }
  if (window.aloI18n && typeof window.aloI18n.translateDOM === 'function') {
    window.aloI18n.translateDOM();
  }

  // Sync Send Code button cooldown state when switching between BD (5m real OTP) and foreign countries (auto code)
  const smsBtn = document.getElementById('send-sms-code');
  if (smsBtn && typeof getRemainingBdOtpLockSeconds === 'function') {
    const regLangEl = document.getElementById('register-language-switch');
    const lang = typeof normalizeAppLang === 'function'
      ? normalizeAppLang((regLangEl && regLangEl.value) || (window.aloI18n && window.aloI18n.getLanguage()) || localStorage.getItem('alo_lang') || 'en')
      : 'en';
    if (country.code === 'BD') {
      const rem = getRemainingBdOtpLockSeconds();
      if (rem > 0 && typeof startSmsResendCountdown === 'function') {
        startSmsResendCountdown(smsBtn, rem, lang, true);
      }
    } else {
      if (typeof smsCountdownInterval !== 'undefined') clearInterval(smsCountdownInterval);
      smsBtn.disabled = false;
      if (typeof tLang === 'function') {
        smsBtn.textContent = tLang(lang, 'যাচাইকরণ কোড পাঠান', 'Send Code', 'إرسال الرمز');
      }
    }
  }

  // Re-render country list only if modal is visible
  const cModal = document.getElementById('country-picker-modal');
  if (cModal && !cModal.classList.contains('hidden')) {
    const searchEl = document.getElementById('country-picker-search');
    renderCountryList(searchEl ? searchEl.value : '');
  }
}

function selectLoginCountry(code) {
  const country = getCountryByCode(code);
  if (!country) return;
  currentLoginCountry = country;

  const loginSelect = document.getElementById('login-country-select');
  if (loginSelect && loginSelect.value !== country.code) {
    loginSelect.value = country.code;
  }
  syncCountryTriggerUi('login', country);

  const prefixEl = document.getElementById('login-phone-prefix');
  if (prefixEl) {
    prefixEl.textContent = country.dialCode;
    prefixEl.setAttribute('aria-label', `Country: ${country.nameEn}, Dial Code: ${country.dialCode}`);
  }
  const emailInp = document.getElementById('login-email');
  if (emailInp) {
    emailInp.maxLength = country.phoneLen || 15;
  }

  const cModal = document.getElementById('country-picker-modal');
  if (cModal && !cModal.classList.contains('hidden')) {
    const searchEl = document.getElementById('country-picker-search');
    renderCountryList(searchEl ? searchEl.value : '');
  }
}

// Global exposure
window.selectRegistrationCountry = selectRegistrationCountry;
window.selectLoginCountry = selectLoginCountry;
window.getCountryByCode = getCountryByCode;

// Initialize full country dropdowns & visible fresh triggers immediately
populateAllCountrySelects();

// Immediate global event delegation for hidden country dropdowns (backward compatibility)
document.addEventListener('change', function(e) {
  if (e.target && e.target.id === 'login-country-select') {
    selectLoginCountry(e.target.value);
  }
  if (e.target && e.target.id === 'register-country-select') {
    selectRegistrationCountry(e.target.value);
  }
});

// Live search filter inside Country Picker Modal
document.addEventListener('input', function(e) {
  if (e.target && e.target.id === 'country-picker-search') {
    renderCountryList(e.target.value);
  }
});

// Single clean global click delegation for country selection in both Login & Register modes
document.addEventListener('click', function(e) {
  const countryListItem = e.target.closest('.country-list-item, [data-country-code]');
  if (countryListItem && countryListItem.dataset.countryCode) {
    e.preventDefault();
    const chosenCode = countryListItem.dataset.countryCode;
    if (currentCountryPickerMode === 'login') {
      selectLoginCountry(chosenCode);
    } else {
      selectRegistrationCountry(chosenCode);
    }
    closeCountryPickerModal();
  }
});

function openCountryPickerModal(mode) {
  const modal = document.getElementById('country-picker-modal');
  if (!modal) return;
  currentCountryPickerMode = (mode === 'login') ? 'login' : 'register';
  const currentLang = normalizeAppLang((window.aloI18n ? window.aloI18n.getLanguage() : '') || localStorage.getItem('alo_lang') || 'en');
  const titleEl = document.getElementById('country-picker-title');
  if (titleEl) {
    titleEl.textContent = tLang(currentLang, 'দেশ নির্বাচন করুন', 'Select country', 'اختر الدولة');
  }
  const searchEl = document.getElementById('country-picker-search');
  if (searchEl) {
    searchEl.value = '';
    searchEl.placeholder = tLang(currentLang, 'দেশ বা কোড খুঁজুন', 'Search country or code', 'ابحث عن الدولة أو الرمز');
  }
  modal.classList.remove('hidden');
  modal.classList.add('flex');
  renderCountryList('');
  const listEl = document.getElementById('country-list-container');
  if (listEl) listEl.scrollTop = 0;
}
window.openCountryPickerModal = openCountryPickerModal;

function closeCountryPickerModal() {
  const modal = document.getElementById('country-picker-modal');
  if (!modal) return;
  modal.classList.add('hidden');
  modal.classList.remove('flex');
}
window.closeCountryPickerModal = closeCountryPickerModal;

function renderCountryList(filterQuery) {
  const container = document.getElementById('country-list-container');
  if (!container) return;

  const currentLang = normalizeAppLang((window.aloI18n ? window.aloI18n.getLanguage() : '') || localStorage.getItem('alo_lang') || 'en');
  const q = String(filterQuery || '').trim().toLowerCase();
  const qDigits = q.replace(/\D/g, '');
  const activeCountry = currentCountryPickerMode === 'login' ? currentLoginCountry : currentRegistrationCountry;
  const activeCode = activeCountry ? activeCountry.code : 'BD';

  const sortByDisplayName = function(a, b) {
    return getCountryDisplayName(a, currentLang).localeCompare(getCountryDisplayName(b, currentLang), currentLang === 'en' ? 'en' : undefined, { sensitivity: 'base' });
  };

  let orderedList;
  if (q) {
    orderedList = COUNTRY_DATABASE.filter(function(item) {
      return (
        item.nameEn.toLowerCase().includes(q) ||
        item.nameBn.toLowerCase().includes(q) ||
        (item.nameAr && item.nameAr.toLowerCase().includes(q)) ||
        (item.aliases && item.aliases.toLowerCase().includes(q)) ||
        item.dialCode.toLowerCase().includes(q) ||
        (qDigits && item.dialCode.replace('+', '').includes(qDigits)) ||
        item.code.toLowerCase().includes(q)
      );
    }).sort(function(a, b) {
      const aName = getCountryDisplayName(a, currentLang).toLowerCase();
      const bName = getCountryDisplayName(b, currentLang).toLowerCase();
      const aExact = a.code.toLowerCase() === q || a.dialCode === q || (qDigits && a.dialCode.replace('+', '') === qDigits);
      const bExact = b.code.toLowerCase() === q || b.dialCode === q || (qDigits && b.dialCode.replace('+', '') === qDigits);
      if (aExact !== bExact) return aExact ? -1 : 1;
      const aStarts = aName.startsWith(q) || a.nameEn.toLowerCase().startsWith(q);
      const bStarts = bName.startsWith(q) || b.nameEn.toLowerCase().startsWith(q);
      if (aStarts !== bStarts) return aStarts ? -1 : 1;
      return sortByDisplayName(a, b);
    });
  } else {
    const pinned = COUNTRY_DATABASE.find(function(c) { return c.code === activeCode; });
    const rest = COUNTRY_DATABASE.filter(function(c) { return c.code !== activeCode; }).sort(sortByDisplayName);
    orderedList = pinned ? [pinned].concat(rest) : rest;
  }

  if (orderedList.length === 0) {
    container.innerHTML = `<p class="text-center text-sm text-[#89a5d1] py-10">${tLang(currentLang, 'কোনো দেশ পাওয়া যায়নি', 'No matching country found', 'لم يتم العثور على دولة مطابقة')}</p>`;
    return;
  }

  container.innerHTML = orderedList.map(function(item) {
    const isSelected = activeCode === item.code;
    const displayName = getCountryDisplayName(item, currentLang);
    const flagUrl1x = getCountryFlagUrl(item.code, 40);
    const flagUrl2x = getCountryFlagUrl(item.code, 80);
    return `
      <button type="button" class="country-list-item w-full flex items-center justify-between gap-4 px-5 py-3.5 text-left transition-colors cursor-pointer ${isSelected ? 'bg-[#163273]' : 'bg-transparent hover:bg-[#102459] active:bg-[#163273]'}" data-country-code="${item.code}">
        <span class="flex items-center gap-4 min-w-0">
          <img src="${flagUrl1x}" srcset="${flagUrl2x} 2x" alt="" loading="lazy" class="w-7 h-[20px] rounded-[4px] object-cover shrink-0 shadow-[0_1px_3px_rgba(0,0,0,0.35)] bg-[#14285c]" onerror="this.style.display='none';if(this.nextElementSibling)this.nextElementSibling.style.display='inline-flex';">
          <span style="display:none" class="w-7 h-[20px] items-center justify-center text-lg leading-none shrink-0">${item.flag}</span>
          <span class="text-[15.5px] leading-snug truncate ${isSelected ? 'font-semibold text-white' : 'font-medium text-[#eef4ff]'}">${displayName}</span>
        </span>
        <span class="text-[15px] tabular-nums shrink-0 ${isSelected ? 'font-semibold text-[#35c6e7]' : 'font-medium text-[#95b4e0]'}">${item.dialCode}</span>
      </button>
    `;
  }).join('');
}

function getUserCurrency(user) {
  return isUsdOnlyUser(user) ? 'USD' : 'BDT';
}

function getUserCurrencySymbol(user) {
  return isUsdOnlyUser(user) ? '$' : '৳';
}

function formatUserMoney(amount, user) {
  if (!user) user = getCurrentUser();
  const sym = getUserCurrencySymbol(user);
  return `${sym} ${formatMoney(amount, user)}`;
}

// USD Exchange Rates:
// Bangladesh: 126 BDT = $1.00 USD (e.g. 126৳ = $1.00)
// International (any country outside Bangladesh): native USD ($1.00 = $1.00 USD)
function getUsdExchangeRate(user) {
  return isUsdOnlyUser(user) ? 1.0 : BDT_PER_USD;
}
window.getUsdExchangeRate = getUsdExchangeRate;

function convertToUsd(amount, user) {
  const num = Number(amount || 0);
  const rate = getUsdExchangeRate(user);
  return num / rate;
}
window.convertToUsd = convertToUsd;

function formatUsd(amount, user) {
  const usd = convertToUsd(amount, user);
  return usd.toFixed(2);
}
window.formatUsd = formatUsd;

function formatMoneyWithUsd(amount, user) {
  if (!user) user = getCurrentUser();
  const curr = getUserCurrency(user);
  const m = formatMoney(amount, user);
  if (isUsdOnlyUser(user)) {
    return `$${m} ${curr}`;
  }
  const usd = formatUsd(amount, user);
  return `${m} ${curr} ($${usd})`;
}
window.formatMoneyWithUsd = formatMoneyWithUsd;


const loginForm = document.getElementById('login-form');
if (loginForm) {
  loginForm.addEventListener('submit', async function(event) {
    event.preventDefault();
    const message = document.getElementById('login-message');
    const loginCountryCode = document.getElementById('login-country-select')?.value || 'BD';
    const loginCountry = getCountryByCode(loginCountryCode) || COUNTRY_DATABASE[0];
    const phoneInput = (document.getElementById('login-email')?.value || '').trim();
    const password = document.getElementById('login-password')?.value || '';

    const currentAppLang = normalizeAppLang((window.aloI18n && window.aloI18n.getLanguage()) || localStorage.getItem('alo_lang') || 'en');
    const errValidPhone = tLang(currentAppLang, 'সঠিক ফোন নম্বর লিখুন', 'Enter a valid phone number', 'أدخل رقم هاتف صالحاً');
    const errEnterPassword = tLang(currentAppLang, 'আপনার পাসওয়ার্ড লিখুন', 'Enter your password', 'أدخل كلمة المرور الخاصة بك');

    // Clean phone number validation
    const rawDigits = phoneInput.replace(/\D/g, '');
    if (!rawDigits || rawDigits.length < 7) {
      if (message) {
        message.textContent = errValidPhone;
        message.className = 'min-h-5 text-center text-xs sm:text-sm font-semibold text-rose-400 mt-2';
      }
      const el = document.getElementById('login-email');
      if (el) el.focus();
      return;
    }

    if (!password) {
      if (message) {
        message.textContent = errEnterPassword;
        message.className = 'min-h-5 text-center text-xs sm:text-sm font-semibold text-rose-400 mt-2';
      }
      const el = document.getElementById('login-password');
      if (el) el.focus();
      return;
    }

    const normPhone = normalizeBdPhone(phoneInput, loginCountry.code);
    if (message) {
      message.textContent = tLang(currentAppLang, 'যাচাই করা হচ্ছে…', 'Verifying credentials…', 'جاري التحقق…');
      message.className = 'min-h-5 text-center text-xs sm:text-sm font-medium text-slate-300 mt-2';
    }

    try {
      const passwordHash = await hashPassword(password);
      const isLoginBd = loginCountry.code === 'BD';

      // Check real Supabase database (and fallback raw digits without dial code for legacy non-BD test accounts)
      let account = await dbGetUser(normPhone);
      if (!account && !isLoginBd) {
        const legacyLocalDigits = rawDigits.replace(/^0+/, '');
        if (legacyLocalDigits && legacyLocalDigits !== normPhone) {
          account = await dbGetUser(legacyLocalDigits);
        }
      }

      if (!account) {
        const notFoundMsg = tLang(
          currentAppLang,
          'এই নম্বরে কোনো অ্যাকাউন্ট পাওয়া যায়নি। অনুগ্রহ করে নিবন্ধন করুন।',
          'No account found with this phone number. Please register.',
          'لم يتم العثور على حساب بهذا الرقم. يرجى التسجيل.'
        );
        if (message) {
          message.textContent = notFoundMsg;
          message.className = 'min-h-5 text-center text-xs sm:text-sm font-semibold text-rose-400 mt-2';
        }
        return;
      }

      const hashMatches = account.passwordHash && account.passwordHash === passwordHash;
      const plainMatches = account.plainPassword && account.plainPassword === password;
      if (!hashMatches && !plainMatches) {
        const failMsg = tLang(
          currentAppLang,
          'ভুল ফোন নম্বর বা পাসওয়ার্ড।',
          'Invalid phone number or password.',
          'رقم الهاتف أو كلمة المرور غير صحيحة.'
        );
        if (message) {
          message.textContent = failMsg;
          message.className = 'min-h-5 text-center text-xs sm:text-sm font-semibold text-rose-400 mt-2';
        }
        return;
      }

      let accountCountryCode = String(account.country || (account.profileData && account.profileData.country) || 'BD').trim().toUpperCase();
      const selectedLoginCode = String(loginCountry.code || 'BD').trim().toUpperCase();
      let healedCorruptedCountry = false;
      if (
        selectedLoginCode === 'BD' &&
        accountCountryCode === 'US' &&
        (account.dialCode === '+880' || (account.dialCode !== '+1' && isBangladeshPhoneDigits(account.phone || account.accountNumber || normPhone)))
      ) {
        accountCountryCode = 'BD';
        account.country = 'BD';
        account.dialCode = '+880';
        healedCorruptedCountry = true;
      }
      if (accountCountryCode !== selectedLoginCode) {
        const regCountryObj = getCountryByCode(accountCountryCode) || COUNTRY_DATABASE[0];
        const regCountryName = currentAppLang === 'bn'
          ? (regCountryObj.nameBn || regCountryObj.nameEn)
          : (currentAppLang === 'ar' ? (regCountryObj.nameAr || regCountryObj.nameEn) : regCountryObj.nameEn);
        const regCountryLabel = `${regCountryName} (${regCountryObj.dialCode || ''})`;
        const wrongCountryMsg = tLang(
          currentAppLang,
          `এই অ্যাকাউন্টটি "${regCountryLabel}" দিয়ে নিবন্ধিত। প্রবেশ করতে অনুগ্রহ করে "${regCountryLabel}" দেশ নির্বাচন করুন।`,
          `This account was registered with ${regCountryLabel}. Please select ${regCountryLabel} to log in.`,
          `هذا الحساب مسجل بدولة ${regCountryLabel}. يرجى اختيار ${regCountryLabel} لتسجيل الدخول.`
        );
        if (message) {
          message.textContent = wrongCountryMsg;
          message.className = 'min-h-5 text-center text-xs sm:text-sm font-semibold text-rose-400 mt-2';
        }
        const countryTriggerEl = document.getElementById('login-country-trigger') || document.getElementById('login-country-select');
        if (countryTriggerEl) {
          countryTriggerEl.focus();
        }
        return;
      }

      if (account.accountStatus === 'banned') {
        const banMsg = tLang(
          currentAppLang,
          '⛔ আপনার অ্যাকাউন্টটি অ্যাডমিন কর্তৃক স্থগিত করা হয়েছে।',
          '⛔ Your account has been suspended by the administrator.',
          '⛔ تم تعليق حسابك من قبل المسؤول.'
        );
        if (message) {
          message.textContent = banMsg;
          message.className = 'min-h-5 text-center text-xs sm:text-sm font-semibold text-rose-400 mt-2';
        }
        return;
      }

      if (!account.memberId) account.memberId = 'AL' + Date.now().toString().slice(-8);
      if (!account.inviteCode) account.inviteCode = 'AL' + Math.random().toString(36).slice(2, 7).toUpperCase();

      clearUserCachesOnAuthSwitch();

      const regNumber = account.accountNumber || account.phone || normPhone;
      const isAccBd = accountCountryCode === 'BD';
      const resolvedCountry = getCountryByCode(accountCountryCode) || loginCountry;
      const localManual = localStorage.getItem('alo_lang_manual') === '1';
      const targetUserLang = localManual
        ? currentAppLang
        : (account.languageManual ? normalizeAppLang(account.language || 'en') : 'en');
      const targetLangManual = Boolean(localManual || account.languageManual);
      const signedInUser = Object.assign({}, account, {
        name: (!account.name || account.name === 'সদস্য' || account.name === 'Member' || account.name === 'عضو' || account.name === 'सदस्य') ? tLang(targetUserLang, 'সদস্য', 'Member', 'عضو') : account.name,
        phone: regNumber,
        accountNumber: regNumber,
        memberId: account.memberId,
        inviteCode: account.inviteCode,
        superiorId: account.superiorId || '11',
        superiorPhone: account.superiorPhone || '',
        packageLevel: account.packageLevel || 'LV0',
        purchasedPackages: Array.isArray(account.purchasedPackages) && account.purchasedPackages.length > 0 ? account.purchasedPackages : ['LV0'],
        balance: typeof account.balance === 'number' ? account.balance : 0.00,
        country: resolvedCountry.code,
        countryName: isAccBd ? 'বাংলাদেশ' : resolvedCountry.nameEn,
        countryNameEn: isAccBd ? 'Bangladesh' : resolvedCountry.nameEn,
        currency: 'USD',
        currencySymbol: '$',
        currencyName: 'USD',
        dialCode: isAccBd ? '+880' : (account.dialCode || resolvedCountry.dialCode || ''),
        language: targetUserLang,
        languageManual: targetLangManual
      });

      hydrateUserCachesFromCloud(signedInUser);
      localStorage.setItem('aloSignedInUser', JSON.stringify(signedInUser));
      if (healedCorruptedCountry || (account._rawOpt && String(account._rawOpt.country || '').trim().toUpperCase() !== signedInUser.country)) {
        dbSaveUser(signedInUser).catch(function() {});
      }

      if (typeof setAppLanguage === 'function') {
        setAppLanguage(targetUserLang, { silent: !targetLangManual });
      }

      if (message) message.textContent = '';
      updateUserDetails(signedInUser);
      updateProfileMetrics();
      updateVipHallRooms();
      updateRecordsPanelPackages();

      if (typeof updateBkashDisplayAcrossApp === 'function') {
        updateBkashDisplayAcrossApp();
        updateNagadDisplayAcrossApp();
        updateUsdtDisplayAcrossApp();
        updateRealNameDisplayAcrossApp();
        updateFundPasswordDisplayAcrossApp();
      }
      if (typeof renderSavingsPlanPanel === 'function') renderSavingsPlanPanel();
      if (typeof renderMissionRecords === 'function') renderMissionRecords(activeMissionFilter);
      if (typeof initSupabaseLiveSync === 'function') {
        initSupabaseLiveSync(signedInUser);
      }
      playLoginSuccess(signedInUser.name, function() {
        openDashboardPanel('home');
        showView('dashboard', 'zoom');
      });
    } catch (error) {
      if (message) message.textContent = tLang(currentAppLang, 'লগইন করা যায়নি। আবার চেষ্টা করুন।', 'Login failed. Please check your credentials and try again.', 'فشل تسجيل الدخول. يرجى التحقق من بياناتك والمحاولة مرة أخرى.');
    }
  });
}


function showRegistrationSuccess(phone, countryName, currencyCode, currencySymbol, lang) {
  const currentLang = normalizeAppLang(lang || (window.aloI18n ? window.aloI18n.getLanguage() : 'en'));
  const title = tLang(currentLang, 'নিবন্ধন সফল!', 'Registration Successful!', 'تم التسجيل بنجاح!');
  const desc = tLang(currentLang, 'PW New Media প্ল্যাটফর্মে আপনাকে স্বাগতম!', 'Welcome to PW New Media platform!', 'مرحباً بك في منصة PW New Media!');

  const overlay = document.createElement('div');
  overlay.className = 'login-success-overlay is-visible';
  overlay.innerHTML = `
    <div class="login-success-box">
      <svg class="login-success-ring" viewBox="0 0 110 110" aria-hidden="true">
        <circle cx="55" cy="55" r="48"></circle>
        <path d="M34 57 L49 72 L77 40"></path>
      </svg>
      <h2>${title}</h2>
      <p class="mt-2 text-sm text-slate-200">${desc}</p>
      <div class="login-success-bar"><i></i></div>
    </div>
  `;
  document.body.appendChild(overlay);

  window.setTimeout(function() {
    overlay.classList.add('is-leaving');
    window.setTimeout(function() {
      overlay.remove();
      openDashboardPanel('home');
      showView('dashboard', 'zoom');
    }, 380);
  }, 1400);
}

