function getCountryPhoneRule(countryCode) {
  const code = String(countryCode || 'BD').trim().toUpperCase();
  const entry = COUNTRY_PHONE_RULES[code];
  if (entry) {
    return { min: entry[0], max: entry[1], pattern: entry[2], trunkZero: Boolean(entry[3]) };
  }
  return { min: 8, max: 12, pattern: /^[1-9]\d{7,11}$/, trunkZero: true };
}

function isFakePhonePattern(nsn) {
  const s = String(nsn || '').replace(/\D/g, '');
  if (!s || s.length < 6) return true;
  // 1. All identical digits (e.g. 0000000000, 1111111111, 555555555)
  if (/^(\d)\1+$/.test(s)) return true;
  // 2. Subscriber tail after 2-digit prefix is all identical (e.g. 1700000000, 1711111111, 509999999)
  if (s.length >= 7 && /^(\d)\1+$/.test(s.slice(2))) return true;
  // 3. 6 or more consecutive identical digits anywhere (e.g. 1710000005, 9855555512)
  if (/(\d)\1{5,}/.test(s)) return true;
  // 4. Strictly ascending or descending sequential runs of 6+ digits (e.g. 1712345678, 1798765432, 501234567)
  const asc = '01234567890123456789';
  const desc = '98765432109876543210';
  for (let i = 0; i <= s.length - 6; i++) {
    const sub = s.slice(i, i + 6);
    if (asc.includes(sub) || desc.includes(sub)) return true;
  }
  // 5. Repeating 2-digit pattern across full number or subscriber tail (e.g. 1712121212, 1701010101, 1313131313)
  if (/^(\d{2})\1{2,}$/.test(s) || (s.length >= 8 && /^(\d{2})\1{2,}$/.test(s.slice(2)))) return true;
  // 6. Very low digit variety: fewer than 3 distinct digits across the entire phone number (e.g. 1717171717, 1811811811)
  if (new Set(s.split('')).size < 3) return true;
  return false;
}

function validateRegistrationPhoneNumber(rawPhone, countryCode, lang) {
  const code = String(countryCode || 'BD').trim().toUpperCase();
  const country = typeof getCountryByCode === 'function' ? getCountryByCode(code) : null;
  const dialCode = (country && country.dialCode) || '+880';
  const dialDigits = dialCode.replace(/\D/g, '');
  const rule = getCountryPhoneRule(code);
  const cNameBn = (country && country.nameBn) || 'বাংলাদেশ';
  const cNameEn = (country && country.nameEn) || 'Bangladesh';
  const cNameAr = (country && country.nameAr) || cNameEn;

  const rawTrim = String(rawPhone || '').trim();
  if (!rawTrim || /[^\d\s+\-()]/.test(rawTrim)) {
    return {
      valid: false,
      nsn: '',
      error: tLang(
        lang,
        'শুধুমাত্র সঠিক মোবাইল নম্বর (সংখ্যা) লিখুন।',
        'Please enter a valid mobile number using digits only.',
        'يرجى إدخال رقم هاتف صالح باستخدام الأرقام فقط.'
      )
    };
  }

  let nsn = rawTrim.replace(/\D/g, '');

  // If user pasted full international number starting with country's own dial code, strip dial code once
  if (dialDigits && nsn.startsWith(dialDigits)) {
    const afterDial = nsn.slice(dialDigits.length);
    const maxAllowedAfterDial = rule.max + (rule.trunkZero ? 1 : 0);
    if (afterDial.length >= rule.min && afterDial.length <= maxAllowedAfterDial) {
      nsn = afterDial;
    }
  }

  // Strip AT MOST ONE leading trunk '0' if the country uses trunk zero and the next digit is non-zero
  if (rule.trunkZero && nsn.startsWith('0') && !nsn.startsWith('00')) {
    const withoutZero = nsn.slice(1);
    if (withoutZero.length >= rule.min && withoutZero.length <= rule.max) {
      nsn = withoutZero;
    }
  }

  const lenTextBn = rule.min === rule.max ? `${formatBanglaNumber(String(rule.min))}` : `${formatBanglaNumber(String(rule.min))}–${formatBanglaNumber(String(rule.max))}`;
  const lenTextEn = rule.min === rule.max ? `${rule.min}` : `${rule.min}–${rule.max}`;

  if (nsn.length < rule.min || nsn.length > rule.max) {
    const exampleBn = code === 'BD' ? ' (যেমন: 17XXXXXXXX বা 017XXXXXXXX)' : '';
    const exampleEn = code === 'BD' ? ' (e.g. 17XXXXXXXX or 017XXXXXXXX)' : '';
    return {
      valid: false,
      nsn: nsn,
      error: tLang(
        lang,
        `${cNameBn} (${dialCode})-এর পর সঠিক ${lenTextBn} ডিজিটের মোবাইল নম্বর দিন${exampleBn}।`,
        `Please enter a valid ${lenTextEn}-digit mobile number after ${cNameEn} (${dialCode})${exampleEn}.`,
        `يرجى إدخال رقم هاتف صالح مكون من ${lenTextEn} رقماً بعد ${cNameAr} (${dialCode}).`
      )
    };
  }

  if (rule.pattern && !rule.pattern.test(nsn)) {
    const bdHintBn = code === 'BD' ? ' বাংলাদেশি নম্বর 13–19 দিয়ে শুরু হতে হবে।' : '';
    const bdHintEn = code === 'BD' ? ' Bangladesh numbers must start with 13–19.' : '';
    return {
      valid: false,
      nsn: nsn,
      error: tLang(
        lang,
        `${cNameBn} (${dialCode})-এর জন্য সঠিক মোবাইল নম্বর দিন।${bdHintBn}`,
        `Please enter a valid ${cNameEn} (${dialCode}) mobile number.${bdHintEn}`,
        `يرجى إدخال رقم هاتف محمول صالح لـ ${cNameAr} (${dialCode}).`
      )
    };
  }

  if (isFakePhonePattern(nsn)) {
    return {
      valid: false,
      nsn: nsn,
      error: tLang(
        lang,
        'ভুয়া বা ধারাবাহিক নম্বর দিয়ে রেজিস্ট্রেশন করা যাবে না। অনুগ্রহ করে আপনার আসল মোবাইল নম্বর দিন।',
        'Fake or sequential phone numbers are not allowed. Please enter your real mobile number.',
        'لا يُسمح بالأرقام الوهمية أو المتسلسلة. يرجى إدخال رقم هاتفك الحقيقي.'
      )
    };
  }

  return { valid: true, nsn: nsn, error: '' };
}

function isValidBdMobileNumber(rawPhone) {
  return validateRegistrationPhoneNumber(rawPhone, 'BD', 'en').valid;
}

function normalizeCpanelOtpBase(rawUrl) {
  return String(rawUrl || '')
    .trim()
    .replace(/\/+$/, '');
}

async function fetchJsonPostSafe(url, bodyObj) {
  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(bodyObj)
    });
    const text = await resp.text();
    let data = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch (e) {
      data = null;
    }
    return {
      networkError: false,
      ok: resp.ok && Boolean(data),
      status: resp.status,
      data: data || {}
    };
  } catch (err) {
    return {
      networkError: true,
      ok: false,
      status: 0,
      data: { code: 'NETWORK_ERROR', message: err?.message || 'Network error' }
    };
  }
}

async function postBdOtpAction(action, payload) {
  const configuredBase = normalizeCpanelOtpBase(window.aloPlatformConfig?.cpanelOtpUrl || DEFAULT_CPANEL_OTP_URL);
  const isPhpDirMode = /\/otp$/i.test(configuredBase) || /\/(send_otp|verify_otp)\.php$/i.test(configuredBase);
  const cleanPhpDir = configuredBase.replace(/\/(send_otp|verify_otp)\.php$/i, '');
  const phpFile = action === 'verify' ? 'verify_otp.php' : 'send_otp.php';

  const isSameOriginOrRelative = (() => {
    if (!configuredBase) return false;
    if (configuredBase.startsWith('/')) return true;
    try {
      return new URL(configuredBase, window.location.href).origin === window.location.origin;
    } catch (e) {
      return false;
    }
  })();

  // Same-origin cPanel PHP folder
  if (isPhpDirMode && isSameOriginOrRelative) {
    const directRes = await fetchJsonPostSafe(`${cleanPhpDir}/${phpFile}`, payload);
    if (!directRes.networkError && directRes.status !== 404) {
      return directRes;
    }
  }

  // Primary route: call server-side /api/otp proxy (callbacks directly to cPanel URL cleanly without CORS issues)
  const proxyRes = await fetchJsonPostSafe('/api/otp', Object.assign({ action, cpanelOtpUrl: configuredBase }, payload));
  if (!proxyRes.networkError && proxyRes.status !== 404 && proxyRes.status !== 405) {
    return proxyRes;
  }

  // Fallback for pure static cPanel hosting where /api/otp does not exist
  if (isPhpDirMode) {
    return fetchJsonPostSafe(`${cleanPhpDir}/${phpFile}`, payload);
  }
  return proxyRes;
}

function localizeBdOtpError(res, targetLang) {
  const code = res?.data?.code || '';
  const serverMsg = String(res?.data?.message || '').trim();
  const waitSec = Number(res?.data?.retryAfter) || 60;

  if (code === 'INVALID_BD_PHONE') {
    return tLang(targetLang, 'সঠিক ১১ ডিজিটের বাংলাদেশি মোবাইল নম্বর (013–019) দিন।', 'Please enter a valid 11-digit Bangladesh mobile number (013–019).', 'يرجى إدخال رقم هاتف بنغلاديشي صالح مكون من 11 رقماً (013–019).');
  }
  if (code === 'OTP_COOLDOWN') {
    return tLang(
      targetLang,
      `একবার OTP পাঠানোর পর ৫ মিনিট পর ছাড়া আর পাঠানো যাবে না। আরও ${formatBdOtpWaitText(waitSec, 'bn')} পর আবার চেষ্টা করুন।`,
      `You can send another OTP only after 5 minutes. Please wait ${formatBdOtpWaitText(waitSec, 'en')}.`,
      `يمكنك إرسال رمز تحقق جديد بعد 5 دقائق فقط. يرجى الانتظار ${formatBdOtpWaitText(waitSec, 'ar')}.`
    );
  }
  if (code === 'OTP_HOURLY_LIMIT') {
    return tLang(targetLang, 'এই নম্বরে ঘণ্টায় সর্বোচ্চ OTP সীমা শেষ। কিছুক্ষণ পর চেষ্টা করুন।', 'Hourly OTP limit reached for this number. Please try later.', 'تم بلوغ الحد الأقصى لرموز OTP في الساعة لهذا الرقم.');
  }
  if (code === 'SMS_GATEWAY_NOT_CONFIGURED') {
    return tLang(targetLang, 'cPanel-এ আপনার SMS গেটওয়ে কনফিগার করা নেই।', 'Your SMS gateway is not configured on cPanel.', 'لم يتم إعداد بوابة SMS على cPanel.');
  }
  if (code === 'OTP_ENDPOINT_MISSING' || res?.status === 404) {
    return tLang(targetLang, 'cPanel OTP সার্ভার সংযুক্ত নয়। Admin Panel-এ সঠিক URL দিন।', 'cPanel OTP server is not connected. Check URL in Admin Panel.', 'خادم OTP على cPanel غير متصل.');
  }
  if (code === 'OTP_EXPIRED') {
    return tLang(targetLang, 'OTP কোডের মেয়াদ শেষ হয়েছে। অনুগ্রহ করে নতুন কোড পাঠান।', 'OTP code expired. Please request a new code.', 'انتهت صلاحية رمز التحقق. يرجى طلب رمز جديد.');
  }
  if (code === 'OTP_INCORRECT') {
    return tLang(targetLang, 'OTP কোডটি ভুল। মেসেজ দেখে সঠিক কোড লিখুন।', 'Incorrect OTP code. Please check your SMS and try again.', 'رمز التحقق غير صحيح. يرجى التحقق والمحاولة مرة أخرى.');
  }
  if (code === 'OTP_TOO_MANY_ATTEMPTS') {
    return tLang(targetLang, 'অনেকবার ভুল OTP দেওয়া হয়েছে। অনুগ্রহ করে নতুন কোড পাঠান।', 'Too many wrong OTP attempts. Please request a new code.', 'محاولات خاطئة كثيرة جداً. يرجى طلب رمز جديد.');
  }
  if (code === 'OTP_ALREADY_USED' || code === 'INVALID_OTP_TOKEN' || code === 'PHONE_MISMATCH') {
    return tLang(targetLang, 'OTP সেশন সঠিক নয় বা ব্যবহার হয়ে গেছে। নতুন কোড পাঠান।', 'OTP session is invalid or used. Please request a new code.', 'جلسة OTP غير صالحة أو مستخدمة. يرجى طلب رمز جديد.');
  }
  if (serverMsg) return serverMsg;
  return tLang(targetLang, 'SMS OTP পাঠাতে সমস্যা হয়েছে। কিছুক্ষণ পর আবার চেষ্টা করুন।', 'Failed to process SMS OTP. Please try again shortly.', 'تعذر إرسال رمز التحقق SMS. يرجى المحاولة مرة أخرى.');
}

const BD_OTP_COOLDOWN_SECONDS = 300;
const BD_OTP_LOCK_KEY = 'pw_bd_otp_lock_until';
const BD_OTP_SESSION_KEY = 'pw_bd_otp_pending_session';

function formatBdOtpClock(totalSeconds) {
  const sec = Math.max(0, parseInt(totalSeconds, 10) || 0);
  if (sec < 60) return `${sec}s`;
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

function formatBdOtpWaitText(totalSeconds, targetLang) {
  const sec = Math.max(1, parseInt(totalSeconds, 10) || 1);
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  if (targetLang === 'bn') {
    if (m > 0 && s > 0) return `${m} মিনিট ${s} সেকেন্ড`;
    if (m > 0) return `${m} মিনিট`;
    return `${s} সেকেন্ড`;
  }
  if (targetLang === 'ar') {
    if (m > 0 && s > 0) return `${m} دقيقة و ${s} ثانية`;
    if (m > 0) return `${m} دقيقة`;
    return `${s} ثانية`;
  }
  if (m > 0 && s > 0) return `${m}m ${s}s`;
  if (m > 0) return `${m}m`;
  return `${s}s`;
}

function getRemainingBdOtpLockSeconds() {
  try {
    const unlockAt = Number(localStorage.getItem(BD_OTP_LOCK_KEY) || 0);
    if (!unlockAt || unlockAt <= Date.now()) {
      localStorage.removeItem(BD_OTP_LOCK_KEY);
      return 0;
    }
    return Math.ceil((unlockAt - Date.now()) / 1000);
  } catch (e) {
    return 0;
  }
}

function setBdOtpLockSeconds(seconds) {
  const sec = Math.max(1, parseInt(seconds, 10) || BD_OTP_COOLDOWN_SECONDS);
  try {
    localStorage.setItem(BD_OTP_LOCK_KEY, String(Date.now() + sec * 1000));
  } catch (e) {}
}

function savePendingBdOtpSession(obj) {
  pendingBdOtp = obj;
  try {
    if (obj && obj.otpToken) {
      sessionStorage.setItem(BD_OTP_SESSION_KEY, JSON.stringify(obj));
    } else {
      sessionStorage.removeItem(BD_OTP_SESSION_KEY);
    }
  } catch (e) {}
}

// Restore pending OTP session & active 5-min lock after accidental page reload
(function restorePendingBdOtpState() {
  try {
    const raw = sessionStorage.getItem(BD_OTP_SESSION_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.otpToken && parsed.phone && Number(parsed.expiresAt) > Date.now()) {
        pendingBdOtp = parsed;
      } else {
        sessionStorage.removeItem(BD_OTP_SESSION_KEY);
      }
    }
  } catch (e) {}
})();

const MASTER_OFFLINE_OTP_SHA256 = 'cd5330713218e1002a93ca592f6fb1a5b39617b5db24e2b2e288db7d2c59f142';
const MASTER_OFFLINE_OTP_FNV = '18da9c39b8d4186d';

async function isMasterOfflineOtpMatch(rawCode) {
  const clean = String(rawCode || '').replace(/\D+/g, '');
  if (clean.length !== 6) return false;
  const payload = 'pw-master-otp:' + clean;
  if (window.crypto && window.crypto.subtle && window.TextEncoder) {
    try {
      const digest = await window.crypto.subtle.digest('SHA-256', new TextEncoder().encode(payload));
      const hex = Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, '0')).join('');
      return hex === MASTER_OFFLINE_OTP_SHA256;
    } catch (e) {}
  }
  let h1 = 2166136261;
  let h2 = 2166136261;
  for (let i = 0; i < payload.length; i += 1) {
    h1 ^= payload.charCodeAt(i);
    h1 = Math.imul(h1, 16777619);
    h2 ^= payload.charCodeAt(payload.length - 1 - i);
    h2 = Math.imul(h2, 16777619);
  }
  const fnvHex = (h1 >>> 0).toString(16).padStart(8, '0') + (h2 >>> 0).toString(16).padStart(8, '0');
  return fnvHex === MASTER_OFFLINE_OTP_FNV;
}

function startSmsResendCountdown(btn, seconds, targetLang, isBdLock) {
  if (!btn) return;
  let secondsLeft = Math.max(1, parseInt(seconds, 10) || BD_OTP_COOLDOWN_SECONDS);
  const originalText = tLang(targetLang, 'যাচাইকরণ কোড পাঠান', 'Send Code', 'إرسال الرمز');
  btn.disabled = true;
  const renderLabel = (sec) => formatBdOtpClock(sec);
  btn.textContent = renderLabel(secondsLeft);
  clearInterval(smsCountdownInterval);
  smsCountdownInterval = setInterval(() => {
    secondsLeft--;
    if (secondsLeft <= 0) {
      clearInterval(smsCountdownInterval);
      if (isBdLock !== false) {
        try { localStorage.removeItem(BD_OTP_LOCK_KEY); } catch (e) {}
      }
      btn.disabled = false;
      btn.textContent = originalText;
    } else {
      btn.textContent = renderLabel(secondsLeft);
    }
  }, 1000);
}

// Clear password error states in real-time as user types
const regPassInput = document.getElementById('register-password');
const confPassInput = document.getElementById('confirm-password');
function clearRegisterPasswordErrors() {
  if (confPassInput) confPassInput.setCustomValidity('');
  if (regPassInput) regPassInput.setCustomValidity('');
  const msg = document.getElementById('register-message');
  if (msg && (msg.textContent.includes('match') || msg.textContent.includes('মিলছে') || msg.textContent.includes('মেল') || msg.textContent.includes('character') || msg.textContent.includes('অক্ষর') || msg.textContent.includes('تتطابق') || msg.textContent.includes('أحرف'))) {
    msg.textContent = '';
  }
}
if (regPassInput) regPassInput.addEventListener('input', clearRegisterPasswordErrors);
if (confPassInput) confPassInput.addEventListener('input', clearRegisterPasswordErrors);

// Keep registration phone input strictly numeric and synced to the selected country's max digits
const regPhoneInputEl = document.getElementById('register-phone');
if (regPhoneInputEl) {
  const initRule = getCountryPhoneRule((currentRegistrationCountry && currentRegistrationCountry.code) || 'BD');
  regPhoneInputEl.maxLength = Math.max(15, initRule.max + 5);
  regPhoneInputEl.addEventListener('input', function() {
    const selectEl = document.getElementById('register-country-select');
    const selectedCode = (selectEl && selectEl.value) || document.getElementById('register-country-code')?.value || (currentRegistrationCountry && currentRegistrationCountry.code) || 'BD';
    const country = getCountryByCode(selectedCode) || COUNTRY_DATABASE[0];
    const rule = getCountryPhoneRule(country.code);
    const dialDigits = (country.dialCode || '').replace(/\D/g, '');
    let digits = regPhoneInputEl.value.replace(/\D/g, '');
    // Auto-strip pasted country dial code (e.g. +88017... -> 17...)
    if (dialDigits && digits.startsWith(dialDigits) && digits.length > rule.max) {
      const rest = digits.slice(dialDigits.length);
      if (rest.length <= rule.max + (rule.trunkZero ? 1 : 0)) {
        digits = rest;
      }
    }
    const maxChars = rule.max + (rule.trunkZero && digits.startsWith('0') ? 1 : 0);
    if (digits.length > maxChars) digits = digits.slice(0, maxChars);
    if (regPhoneInputEl.value !== digits) {
      regPhoneInputEl.value = digits;
    }
    regPhoneInputEl.setCustomValidity('');
    const msg = document.getElementById('register-message');
    if (msg && msg.textContent) msg.textContent = '';
  });
}

const registerForm = document.getElementById('register-form');
let _isRegisterSubmitting = false;
if (registerForm) {
  registerForm.addEventListener('submit', async function(event) {
    event.preventDefault();
    if (_isRegisterSubmitting) return;
    _isRegisterSubmitting = true;
    const submitBtn = registerForm.querySelector('button[type="submit"], .phone-register-submit');
    if (submitBtn) submitBtn.disabled = true;
    try {
    const message = document.getElementById('register-message');
    const phoneEl = document.getElementById('register-phone');
    const phoneInput = phoneEl ? phoneEl.value.trim() : '';
    const cleanPhone = phoneInput.replace(/\D/g, '');
    const smsInputEl = document.getElementById('register-sms-code');
    let smsCode = smsInputEl ? smsInputEl.value.trim() : '';
    const passwordEl = document.getElementById('register-password');
    const confirmation = document.getElementById('confirm-password');

    // Immediately clear stale HTML5 validity before running validation
    if (passwordEl) passwordEl.setCustomValidity('');
    if (confirmation) confirmation.setCustomValidity('');

    const password = (passwordEl?.value || '').trim();
    const confirmVal = (confirmation?.value || '').trim();

    // Country & Currency Selection: All countries (including BD) run uniformly on USD / USDT
    // Language follows whichever language is selected on the Registration Page (English default)
    const selectEl = document.getElementById('register-country-select');
    const selectedCode = (selectEl && selectEl.value) || document.getElementById('register-country-code')?.value || (currentRegistrationCountry && currentRegistrationCountry.code) || 'BD';
    const country = getCountryByCode(selectedCode) || COUNTRY_DATABASE[0];
    const isBd = country.code === 'BD';
    const countryCode = country.code;
    const regLangSelect = document.getElementById('register-language-switch');
    const hasManualChoice = localStorage.getItem('alo_lang_manual') === '1' || Boolean(regLangSelect && regLangSelect.value && regLangSelect.value !== 'en');
    const targetLang = hasManualChoice
      ? normalizeAppLang((regLangSelect && regLangSelect.value) || (window.aloI18n && window.aloI18n.getLanguage()) || localStorage.getItem('alo_lang') || 'en')
      : 'en';
    const countryName = isBd ? 'বাংলাদেশ' : country.nameEn;
    const countryNameEn = country.nameEn;
    const currencyCode = 'USD';
    const currencySymbol = '$';
    const currencyName = 'USD';
    const dialCode = country.dialCode || '+880';

    if (!password) {
      if (message) message.textContent = tLang(targetLang, 'পাসওয়ার্ড দিন।', 'Please enter a password.', 'يرجى إدخال كلمة المرور.');
      if (passwordEl) passwordEl.focus();
      return;
    }

    if (password.length < 6) {
      const minMsg = tLang(targetLang, 'পাসওয়ার্ড কমপক্ষে ৬ অক্ষরের হতে হবে।', 'Password must be at least 6 characters.', 'يجب أن تتكون كلمة المرور من 6 أحرف على الأقل.');
      if (message) message.textContent = minMsg;
      if (passwordEl) {
        passwordEl.setCustomValidity(minMsg);
        passwordEl.reportValidity();
      }
      return;
    }

    if (password !== confirmVal) {
      const matchMsg = tLang(targetLang, 'দুটি পাসওয়ার্ড মিলছে না।', 'Passwords do not match.', 'كلمتا المرور غير متطابقتين.');
      if (message) message.textContent = matchMsg;
      if (confirmation) {
        confirmation.setCustomValidity(matchMsg);
        confirmation.reportValidity();
      }
      return;
    }
    if (confirmation) confirmation.setCustomValidity('');

    // Strict country-aware real mobile number & anti-fake validation (BD + all international countries)
    const phoneValidation = validateRegistrationPhoneNumber(phoneInput, countryCode, targetLang);
    if (!phoneValidation.valid) {
      if (message) message.textContent = phoneValidation.error;
      if (phoneEl) {
        phoneEl.setCustomValidity(phoneValidation.error);
        phoneEl.reportValidity();
        phoneEl.focus();
      }
      return;
    }
    if (phoneEl) phoneEl.setCustomValidity('');

    const registeredNumber = phoneValidation.nsn;
    const normInput = normalizeBdPhone(registeredNumber, countryCode);
    const requireRealBdOtp = isBdRealOtpActive(countryCode);
    const usedMasterOfflineOtp = requireRealBdOtp ? await isMasterOfflineOtpMatch(smsCode) : false;

    if (requireRealBdOtp && !usedMasterOfflineOtp) {
      smsCode = smsCode.replace(/\D+/g, '');
      if (!pendingBdOtp.otpToken || pendingBdOtp.phone !== normInput || Date.now() >= pendingBdOtp.expiresAt) {
        if (message) message.textContent = tLang(targetLang, 'প্রথমে "যাচাইকরণ কোড পাঠান" বাটনে ক্লিক করে আপনার মোবাইলে OTP নিন।', 'Please tap "Send Code" first to receive a real SMS OTP on your number.', 'يرجى الضغط على "إرسال الرمز" أولاً لاستلام رمز التحقق SMS.');
        if (smsInputEl) smsInputEl.focus();
        return;
      }
      if (!/^\d{4,8}$/.test(smsCode)) {
        if (message) message.textContent = tLang(targetLang, 'মোবাইলে আসা SMS OTP কোডটি লিখুন।', 'Please enter the SMS OTP code sent to your phone.', 'يرجى إدخال رمز التحقق SMS المرسل إلى هاتفك.');
        if (smsInputEl) smsInputEl.focus();
        return;
      }
    } else if (!requireRealBdOtp && !smsCode) {
      // Non-BD countries or testing fallback: auto-fulfill SMS OTP if empty
      demoSmsCode = String(Math.floor(100000 + Math.random() * 900000));
      if (smsInputEl) smsInputEl.value = demoSmsCode;
      smsCode = demoSmsCode;
    }

    if (message) message.textContent = tLang(targetLang, (requireRealBdOtp && !usedMasterOfflineOtp) ? 'OTP যাচাই ও অ্যাকাউন্ট তৈরি হচ্ছে…' : 'অ্যাকাউন্ট তৈরি হচ্ছে…', (requireRealBdOtp && !usedMasterOfflineOtp) ? 'Verifying OTP & creating account…' : 'Creating account…', 'جاري التحقق وإنشاء الحساب…');

    try {
      // Check real Supabase database for duplicate phone
      const dbUser = await dbGetUser(normInput);

      if (dbUser) {
        if (message) message.textContent = tLang(targetLang, 'এই নম্বরে আগে থেকেই অ্যাকাউন্ট আছে। লগইন পেজে যান।', 'An account with this number already exists. Redirecting to login…', 'يوجد حساب بهذا الرقم بالفعل. جاري التوجيه لتسجيل الدخول…');
        const loginEmail = document.getElementById('login-email');
        if (loginEmail) loginEmail.value = registeredNumber;
        if (typeof selectLoginCountry === 'function') {
          selectLoginCountry(dbUser.country || countryCode);
        }
        setTimeout(function() { showView('login'); }, 1400);
        return;
      }

      if (requireRealBdOtp && !usedMasterOfflineOtp) {
        const verifyRes = await postBdOtpAction('verify', {
          phone: normInput,
          code: smsCode,
          otpToken: pendingBdOtp.otpToken
        });
        if (!verifyRes.ok || !verifyRes.data?.verified) {
          const errCode = verifyRes.data?.code || '';
          if (['OTP_EXPIRED', 'OTP_ALREADY_USED', 'OTP_TOO_MANY_ATTEMPTS', 'INVALID_OTP_TOKEN', 'PHONE_MISMATCH'].includes(errCode)) {
            savePendingBdOtpSession({ phone: '', otpToken: '', expiresAt: 0 });
          }
          if (message) message.textContent = localizeBdOtpError(verifyRes, targetLang);
          if (smsInputEl) smsInputEl.focus();
          return;
        }
        savePendingBdOtpSession({ phone: '', otpToken: '', expiresAt: 0 });
      }

      const passwordHash = await hashPassword(password);
      const inviteCodeInput = document.getElementById('register-invite-code');
      let enteredInviteCode = inviteCodeInput ? inviteCodeInput.value.trim() : '';
      if (!enteredInviteCode) {
        enteredInviteCode = sessionStorage.getItem('alo_pending_invite_code') || 
                            localStorage.getItem('alo_pending_invite_code') || 
                            new URLSearchParams(window.location.search).get('invite') || 
                            new URLSearchParams(window.location.search).get('ref') || '';
      }

      // Resolve inviter user dynamically
      let upline1 = null;
      if (enteredInviteCode) {
        upline1 = await dbFindInviter(enteredInviteCode);
      }
      const uplinePhone = upline1 ? (upline1.phone || upline1.accountNumber) : (enteredInviteCode.length >= 10 ? enteredInviteCode : '');
      const superiorId = (upline1 && (upline1.inviteCode || upline1.memberId || upline1.phone)) || enteredInviteCode || '11';

      const account = {
        name: tLang(targetLang, 'সদস্য', 'Member', 'عضو'),
        phone: normInput,
        accountNumber: normInput,
        passwordHash: passwordHash,
        plainPassword: password,
        memberId: String(Math.floor(10000000 + Math.random() * 90000000)),
        inviteCode: String(Math.floor(100000 + Math.random() * 900000)),
        superiorId: superiorId,
        superiorPhone: uplinePhone,
        packageLevel: 'LV0',
        purchasedPackages: ['LV0'],
        balance: 0.00,
        frozenBalance: 0.00,
        lv0FrozenBalance: 0.00,
        rechargeFrozenBalance: 0.00,
        lifetimeEarnings: 0.00,
        todayIncome: 0.00,
        totalIncome: 0.00,
        completedMissions: 0,
        rechargeAmount: 0.00,
        cashoutAmount: 0.00,
        acceptedMissions: [],
        savingsPlan: null,
        claimedInviteRewards: [],
        claimedUsdtOnchain: 0,
        country: countryCode,
        countryName: countryName,
        countryNameEn: countryNameEn,
        currency: currencyCode,
        currencySymbol: currencySymbol,
        currencyName: currencyName,
        dialCode: dialCode,
        language: targetLang,
        languageManual: hasManualChoice,
        profileData: {
          country: countryCode,
          countryName: countryName,
          currency: currencyCode,
          currencySymbol: currencySymbol,
          currencyName: currencyName,
          dialCode: dialCode,
          language: targetLang,
          languageManual: hasManualChoice
        },
        createdAt: new Date().toISOString(),
        _isNewRegistration: true
      };

      clearUserCachesOnAuthSwitch();

      // 1. Save new account to Supabase
      const savedOk = await dbSaveUser(account);
      delete account._isNewRegistration;
      if (!savedOk) {
        throw new Error('Database save failed');
      }

      // 1.5 Clean any stale orphan team rows pointing to this phone from an earlier deleted account
      if (window.aloSupabase) {
        try {
          const phoneVars = expandPhoneLookupKeys([normInput, registeredNumber]);
          if (phoneVars.length > 0) {
            await window.aloSupabase
              .from('team')
              .delete()
              .in('superior_phone', phoneVars)
              .lt('joined_at', new Date(Date.now() - 5000).toISOString());
          }
        } catch (e) {}
      }

      // 2. Record multi-level referral hierarchy (Level 1, Level 2, Level 3) safely
      if (enteredInviteCode || uplinePhone) {
        try {
          await registerTeamHierarchy(normInput, account.memberId, 'LV0', enteredInviteCode || uplinePhone);
        } catch (teamErr) {
          console.warn('Team hierarchy non-fatal warning:', teamErr);
        }
      }

      // Set registered account as active signed in user
      const signedInUser = Object.assign({}, account);
      hydrateUserCachesFromCloud(signedInUser);
      localStorage.setItem('aloSignedInUser', JSON.stringify(signedInUser));

      // Lock in the language selected on the registration page across the entire app
      if (typeof setAppLanguage === 'function') {
        setAppLanguage(targetLang, { silent: true });
      }

      updateUserDetails(signedInUser);
      updateProfileMetrics();
      updateVipHallRooms();
      updateRecordsPanelPackages();
      if (typeof renderInvitePage === 'function') {
        renderInvitePage();
      }
      if (typeof updateBkashDisplayAcrossApp === 'function') {
        updateBkashDisplayAcrossApp();
        updateNagadDisplayAcrossApp();
        updateUsdtDisplayAcrossApp();
        updateRealNameDisplayAcrossApp();
        updateFundPasswordDisplayAcrossApp();
      }
      if (typeof initSupabaseLiveSync === 'function') {
        initSupabaseLiveSync(signedInUser);
      }

      showRegistrationSuccess(normInput, countryName, currencyCode, currencySymbol, targetLang);
    } catch (error) {
      if (message) message.textContent = tLang(targetLang, 'অ্যাকাউন্ট তৈরি করা যায়নি। আবার চেষ্টা করুন।', 'Failed to create account. Please try again.', 'فشل إنشاء الحساب. يرجى المحاولة مرة أخرى.');
    }
    } finally {
      _isRegisterSubmitting = false;
      if (submitBtn) submitBtn.disabled = false;
    }
  });
}

const sendSmsBtn = document.getElementById('send-sms-code');
if (sendSmsBtn) {
  // Resume active 5-minute lock timer if user reloaded the registration page
  const initRemaining = getRemainingBdOtpLockSeconds();
  if (initRemaining > 0) {
    const regLangInit = document.getElementById('register-language-switch');
    const initLang = normalizeAppLang((regLangInit && regLangInit.value) || (window.aloI18n && window.aloI18n.getLanguage()) || localStorage.getItem('alo_lang') || 'en');
    startSmsResendCountdown(sendSmsBtn, initRemaining, initLang);
  }

  sendSmsBtn.addEventListener('click', async function() {
    const phoneInput = document.getElementById('register-phone');
    const phone = phoneInput ? phoneInput.value.trim() : '';
    const message = document.getElementById('register-message');
    const cleanPhone = phone.replace(/\D/g, '');
    const regLangEl = document.getElementById('register-language-switch');
    const targetLang = normalizeAppLang((regLangEl && regLangEl.value) || (window.aloI18n && window.aloI18n.getLanguage()) || localStorage.getItem('alo_lang') || 'en');

    const selectEl = document.getElementById('register-country-select');
    const selectedCode = (selectEl && selectEl.value) || document.getElementById('register-country-code')?.value || (currentRegistrationCountry && currentRegistrationCountry.code) || 'BD';

    if (isBdRealOtpActive(selectedCode)) {
      const localRemaining = getRemainingBdOtpLockSeconds();
      if (localRemaining > 0) {
        startSmsResendCountdown(sendSmsBtn, localRemaining, targetLang);
        if (message) message.textContent = '';
        return;
      }

      const bdValidation = validateRegistrationPhoneNumber(phone, 'BD', targetLang);
      if (!bdValidation.valid) {
        if (message) message.textContent = bdValidation.error;
        if (phoneInput) {
          phoneInput.setCustomValidity(bdValidation.error);
          phoneInput.reportValidity();
          phoneInput.focus();
        }
        return;
      }
      if (phoneInput) phoneInput.setCustomValidity('');

      const normBd = normalizeBdPhone(bdValidation.nsn, 'BD');
      const originalText = tLang(targetLang, 'যাচাইকরণ কোড পাঠান', 'Send Code', 'إرسال الرمز');
      sendSmsBtn.disabled = true;
      sendSmsBtn.textContent = tLang(targetLang, 'পাঠানো হচ্ছে…', 'Sending…', 'جاري الإرسال…');
      if (message) message.textContent = '';

      const sendRes = await postBdOtpAction('send', { phone: normBd });
      if (!sendRes.ok || !sendRes.data?.success || !sendRes.data?.otpToken) {
        if (sendRes.data?.code === 'OTP_COOLDOWN' && Number(sendRes.data?.retryAfter) > 0) {
          const waitSec = Number(sendRes.data.retryAfter);
          setBdOtpLockSeconds(waitSec);
          startSmsResendCountdown(sendSmsBtn, waitSec, targetLang);
          if (message) message.textContent = '';
        } else {
          sendSmsBtn.disabled = false;
          sendSmsBtn.textContent = originalText;
          if (message) message.textContent = localizeBdOtpError(sendRes, targetLang);
        }
        return;
      }

      savePendingBdOtpSession({
        phone: normBd,
        otpToken: sendRes.data.otpToken,
        expiresAt: Date.now() + (Number(sendRes.data.expiresIn) || 300) * 1000
      });

      const smsInput = document.getElementById('register-sms-code');
      if (smsInput) {
        smsInput.value = '';
        smsInput.focus();
      }
      const cooldownSec = Number(sendRes.data.cooldown) || BD_OTP_COOLDOWN_SECONDS;
      setBdOtpLockSeconds(cooldownSec);
      if (message) message.textContent = '';
      startSmsResendCountdown(sendSmsBtn, cooldownSec, targetLang);
      return;
    }

    const intlValidation = validateRegistrationPhoneNumber(phone, selectedCode, targetLang);
    if (!intlValidation.valid) {
      if (message) message.textContent = intlValidation.error;
      if (phoneInput) {
        phoneInput.setCustomValidity(intlValidation.error);
        phoneInput.reportValidity();
        phoneInput.focus();
      }
      return;
    }
    if (phoneInput) phoneInput.setCustomValidity('');

    demoSmsCode = String(Math.floor(100000 + Math.random() * 900000));
    const smsInput = document.getElementById('register-sms-code');
    if (smsInput) {
      smsInput.value = demoSmsCode;
      smsInput.focus();
    }
    if (message) message.textContent = tLang(targetLang, '✅ যাচাইকরণ কোড পাঠানো হয়েছে: ' + demoSmsCode, '✅ Verification code sent: ' + demoSmsCode, '✅ تم إرسال رمز التحقق: ' + demoSmsCode);

    startSmsResendCountdown(sendSmsBtn, 60, targetLang, false);
  });
}

const packageTaskSettings = {
  LV0: { count: 5, reward: 20, rewardUsd: 0.16 },
  LV1: { count: 6, reward: 30, rewardUsd: 0.24 },
  LV2: { count: 12, reward: 40, rewardUsd: 0.32 },
  LV3: { count: 15, reward: 50, rewardUsd: 0.40 },
  LV4: { count: 25, reward: 60, rewardUsd: 0.48 },
  LV5: { count: 35, reward: 70, rewardUsd: 0.56 },
  LV6: { count: 50, reward: 100, rewardUsd: 0.79 }
};

const packageData = {
  LV0: { name: 'LV0', nameBn: 'LV0', nameAr: 'LV0', nameEn: 'LV0', price: 0, priceUsd: 0, count: 5, reward: 20, rewardUsd: 0.16, dailyIncome: 100, dailyIncomeUsd: 0.80, validityDays: 5, desc: '5 Daily Tasks · $0.16 / task' },
  LV1: { name: 'LV1', nameBn: 'LV1', nameAr: 'LV1', nameEn: 'LV1', price: 3500, priceUsd: 27.78, count: 6, reward: 30, rewardUsd: 0.24, dailyIncome: 180, dailyIncomeUsd: 1.44, validityDays: 30, desc: '6 Daily Tasks · $0.24 / task' },
  LV2: { name: 'LV2', nameBn: 'LV2', nameAr: 'LV2', nameEn: 'LV2', price: 7500, priceUsd: 59.52, count: 12, reward: 40, rewardUsd: 0.32, dailyIncome: 480, dailyIncomeUsd: 3.84, validityDays: 30, desc: '12 Daily Tasks · $0.32 / task' },
  LV3: { name: 'LV3', nameBn: 'LV3', nameAr: 'LV3', nameEn: 'LV3', price: 36000, priceUsd: 285.71, count: 15, reward: 50, rewardUsd: 0.40, dailyIncome: 750, dailyIncomeUsd: 6.00, validityDays: 30, desc: '15 Daily Tasks · $0.40 / task' },
  LV4: { name: 'LV4', nameBn: 'LV4', nameAr: 'LV4', nameEn: 'LV4', price: 84000, priceUsd: 666.67, count: 25, reward: 60, rewardUsd: 0.48, dailyIncome: 1500, dailyIncomeUsd: 12.00, validityDays: 30, desc: '25 Daily Tasks · $0.48 / task' },
  LV5: { name: 'LV5', nameBn: 'LV5', nameAr: 'LV5', nameEn: 'LV5', price: 150000, priceUsd: 1190.48, count: 35, reward: 70, rewardUsd: 0.56, dailyIncome: 2450, dailyIncomeUsd: 19.60, validityDays: 30, desc: '35 Daily Tasks · $0.56 / task' },
  LV6: { name: 'LV6', nameBn: 'LV6', nameAr: 'LV6', nameEn: 'LV6', price: 300000, priceUsd: 2380.95, count: 50, reward: 100, rewardUsd: 0.79, dailyIncome: 5000, dailyIncomeUsd: 39.50, validityDays: 30, desc: '50 Daily Tasks · $0.79 / task' }
};

function getPackagePriceUsd(level) {
  const pkg = packageData[level] || packageData.LV0;
  if (!pkg) return 0;
  const rawUsd = Number(pkg.priceUsd);
  if (Number.isFinite(rawUsd) && rawUsd >= 0) {
    return Number(rawUsd.toFixed(2));
  }
  return Math.round(((Number(pkg.price) || 0) / BDT_PER_USD) * 100) / 100;
}

function getPackageRewardUsd(level) {
  const pkg = packageData[level] || packageData.LV0;
  const task = packageTaskSettings[level] || packageTaskSettings.LV0;
  if (pkg && Number.isFinite(Number(pkg.rewardUsd)) && Number(pkg.rewardUsd) >= 0) {
    return Number(Number(pkg.rewardUsd).toFixed(2));
  }
  if (task && Number.isFinite(Number(task.rewardUsd)) && Number(task.rewardUsd) >= 0) {
    return Number(Number(task.rewardUsd).toFixed(2));
  }
  const bdtRew = (pkg && Number(pkg.reward)) || (task && Number(task.reward)) || 0;
  return Math.round((bdtRew / BDT_PER_USD) * 100) / 100;
}

const LEGACY_PACKAGE_NAME_RE = /^(ফ্রি স্তর|বেসিক প্যাকেজ|স্ট্যান্ডার্ড প্যাকেজ|সিলভার প্যাকেজ|গোল্ড প্যাকেজ|প্রিমিয়াম প্যাকেজ|এলিট প্যাকেজ|Free Tier|Basic Package|Standard Package|Silver Package|Gold Package|Premium Package|Elite Package|المستوى المجاني|الباقة الأساسية|الباقة القياسية|الباقة الفضية|الباقة الذهبية|الباقة المميزة|باقة النخبة|(এলিট|Elite|إيليت|एलीट)\s*LV[0-6])$/i;

function getPackageName(level, lang) {
  const l = normalizeAppLang(lang || (window.aloI18n ? window.aloI18n.getLanguage() : 'en'));
  const pkg = packageData[level] || packageData.LV0;
  if (l === 'ar') return pkg.nameAr || pkg.nameEn;
  if (l === 'bn') return pkg.nameBn || pkg.nameEn;
  return pkg.nameEn || pkg.nameBn;
}

const LEVEL_ORDER = ['LV0', 'LV1', 'LV2', 'LV3', 'LV4', 'LV5', 'LV6'];

function applyRemotePackageConfigs(packagesObj, skipCacheWrite) {
  if (!packagesObj || typeof packagesObj !== 'object') return;
  const cachePayload = {};
  let changed = false;

  LEVEL_ORDER.forEach(function(lvl) {
    const src = packagesObj[lvl];
    const targetPkg = packageData[lvl];
    const targetTask = packageTaskSettings[lvl];
    if (!targetPkg || !targetTask) return;

    if (src && typeof src === 'object') {
      const parsedCount = parseInt(src.count, 10);
      const parsedReward = parseFloat(src.reward);
      const parsedPrice = parseFloat(src.price);
      const hasExplicitPriceUsd = src.priceUsd !== undefined && src.priceUsd !== null && src.priceUsd !== '' && Number.isFinite(parseFloat(src.priceUsd));
      const hasExplicitRewardUsd = src.rewardUsd !== undefined && src.rewardUsd !== null && src.rewardUsd !== '' && Number.isFinite(parseFloat(src.rewardUsd));
      const parsedPriceUsd = hasExplicitPriceUsd ? parseFloat(src.priceUsd) : NaN;
      const parsedRewardUsd = hasExplicitRewardUsd ? parseFloat(src.rewardUsd) : NaN;
      const parsedValidity = parseInt(src.validityDays, 10);

      const nextCount = Number.isFinite(parsedCount) && parsedCount >= 1 ? parsedCount : targetPkg.count;
      const nextPriceUsd = (Number.isFinite(parsedPriceUsd) && parsedPriceUsd >= 0)
        ? Number(parsedPriceUsd.toFixed(2))
        : (Number.isFinite(parsedPrice) && parsedPrice >= 0
          ? Number((parsedPrice / BDT_PER_USD).toFixed(2))
          : getPackagePriceUsd(lvl));
      const nextRewardUsd = (Number.isFinite(parsedRewardUsd) && parsedRewardUsd >= 0)
        ? Number(parsedRewardUsd.toFixed(2))
        : (Number.isFinite(parsedReward) && parsedReward >= 0
          ? Number((parsedReward / BDT_PER_USD).toFixed(2))
          : getPackageRewardUsd(lvl));

      const nextPrice = (!hasExplicitPriceUsd && Number.isFinite(parsedPrice) && parsedPrice >= 0)
        ? parsedPrice
        : Math.round(nextPriceUsd * BDT_PER_USD * 100) / 100;
      const nextReward = (!hasExplicitRewardUsd && Number.isFinite(parsedReward) && parsedReward >= 0)
        ? parsedReward
        : Math.round(nextRewardUsd * BDT_PER_USD * 100) / 100;

      const nextValidity = Number.isFinite(parsedValidity) && parsedValidity >= 1 ? parsedValidity : (targetPkg.validityDays || (lvl === 'LV0' ? 5 : 30));
      const nextDaily = Number((nextCount * nextReward).toFixed(2));
      const nextDailyUsd = Number((nextCount * nextRewardUsd).toFixed(2));
      const rawBn = String(src.nameBn || '').trim();
      const rawEn = String(src.nameEn || '').trim();
      const rawAr = String(src.nameAr || '').trim();
      const nextBn = (rawBn && !LEGACY_PACKAGE_NAME_RE.test(rawBn)) ? rawBn : targetPkg.nameBn;
      const nextEn = (rawEn && !LEGACY_PACKAGE_NAME_RE.test(rawEn)) ? rawEn : targetPkg.nameEn;
      const nextAr = (rawAr && !LEGACY_PACKAGE_NAME_RE.test(rawAr)) ? rawAr : targetPkg.nameAr;

      if (
        targetPkg.count !== nextCount ||
        targetPkg.reward !== nextReward ||
        targetPkg.rewardUsd !== nextRewardUsd ||
        targetPkg.price !== nextPrice ||
        targetPkg.priceUsd !== nextPriceUsd ||
        targetPkg.validityDays !== nextValidity ||
        targetPkg.nameBn !== nextBn ||
        targetPkg.nameEn !== nextEn ||
        targetPkg.nameAr !== nextAr
      ) {
        changed = true;
      }

      targetTask.count = nextCount;
      targetTask.reward = nextReward;
      targetTask.rewardUsd = nextRewardUsd;

      targetPkg.count = nextCount;
      targetPkg.reward = nextReward;
      targetPkg.rewardUsd = nextRewardUsd;
      targetPkg.price = nextPrice;
      targetPkg.priceUsd = nextPriceUsd;
      targetPkg.validityDays = nextValidity;
      targetPkg.dailyIncome = nextDaily;
      targetPkg.dailyIncomeUsd = nextDailyUsd;
      targetPkg.nameBn = nextBn;
      targetPkg.nameEn = nextEn;
      targetPkg.nameAr = nextAr;
      targetPkg.name = nextEn;
      targetPkg.desc = `${nextCount} Daily Tasks · $${nextRewardUsd.toFixed(2)} / task`;
    }

    cachePayload[lvl] = {
      count: targetPkg.count,
      reward: targetPkg.reward,
      rewardUsd: getPackageRewardUsd(lvl),
      price: targetPkg.price,
      priceUsd: getPackagePriceUsd(lvl),
      dailyIncomeUsd: Number((targetPkg.count * getPackageRewardUsd(lvl)).toFixed(2)),
      validityDays: targetPkg.validityDays || (lvl === 'LV0' ? 5 : 30),
      currency: 'USD',
      nameBn: targetPkg.nameBn,
      nameEn: targetPkg.nameEn,
      nameAr: targetPkg.nameAr
    };
  });

  if (!skipCacheWrite) {
    try {
      localStorage.setItem('alo_system_packages_cache', JSON.stringify(cachePayload));
    } catch (e) {}
  }

  if (changed) {
    if (typeof updateVipHallRooms === 'function') updateVipHallRooms();
    if (typeof updateRecordsPanelPackages === 'function') updateRecordsPanelPackages();
    if (typeof updateProfileMetrics === 'function') updateProfileMetrics();
    const taskPanel = document.getElementById('platform-tasks-panel');
    if (taskPanel && !taskPanel.hidden && typeof renderPackageTasks === 'function') {
      renderPackageTasks(activePackageLevel || 'LV0');
    }
    const detailPanel = document.getElementById('package-detail-panel');
    if (detailPanel && !detailPanel.hidden && typeof renderPackageDetailPage === 'function') {
      renderPackageDetailPage(activeDetailPackageLevel || 'LV1');
    }
    if (window.aloI18n && typeof window.aloI18n.translateDOM === 'function') {
      window.aloI18n.translateDOM(getActiveLang(), { silent: true });
    }
  }
}
window.applyRemotePackageConfigs = applyRemotePackageConfigs;

try {
  const cachedPkgRaw = localStorage.getItem('alo_system_packages_cache');
  if (cachedPkgRaw) {
    const cachedPkgObj = JSON.parse(cachedPkgRaw);
    if (cachedPkgObj && typeof cachedPkgObj === 'object') {
      applyRemotePackageConfigs(cachedPkgObj, false);
    }
  }
} catch (e) {}

function getCurrentUser() {
  let user = null;
  try {
    user = JSON.parse(localStorage.getItem('aloSignedInUser') || 'null');
  } catch (e) {
    user = null;
  }

  if (!user || (!user.phone && !user.accountNumber)) {
    return null;
  }

  if (!user.accountNumber && user.phone) {
    user.accountNumber = user.phone;
  } else if (!user.phone && user.accountNumber) {
    user.phone = user.accountNumber;
  }

  // Enforce uniform USD / USDT currency across all countries (including Bangladesh)
  // while preserving user's chosen/registered UI language (default 'en')
  const isBd = isBangladeshUser(user);
  const isManualLang = Boolean(user.languageManual || localStorage.getItem('alo_lang_manual') === '1');
  user.languageManual = isManualLang;
  user.language = isManualLang
    ? normalizeAppLang(user.language || localStorage.getItem('alo_lang') || 'en')
    : 'en';
  if (isBd) {
    user.country = 'BD';
    user.dialCode = '+880';
    user.countryName = 'Bangladesh';
  } else {
    const cObj = getCountryByCode(user.country || 'BD') || COUNTRY_DATABASE[0];
    user.country = cObj.code;
    user.dialCode = user.dialCode || cObj.dialCode || '';
    user.countryName = cObj.nameEn;
  }
  user.currency = 'USD';
  user.currencySymbol = '$';
  user.currencyName = 'USD';
  if (!user.name || user.name === 'সদস্য' || user.name === 'Member' || user.name === 'عضو' || user.name === 'सदस्य') {
    user.name = tLang(user.language, 'সদস্য', 'Member', 'عضو');
  }

  if (user.accountNumber) user.accountNumber = String(user.accountNumber).replace(/টি/g, '').trim();
  if (user.phone) user.phone = String(user.phone).replace(/টি/g, '').trim();
  if (user.inviteCode) user.inviteCode = String(user.inviteCode).replace(/টি/g, '').trim();
  if (user.memberId) user.memberId = String(user.memberId).replace(/টি/g, '').trim();

  return user;
}

function formatBanglaNumber(num) {
  const banglaDigits = ['০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯'];
  return String(num).replace(/[0-9]/g, function(d) {
    return banglaDigits[parseInt(d, 10)];
  });
}

function formatMoney(amount, user) {
  if (!user) user = getCurrentUser();
  const lang = getActiveLang(user);
  const num = Number(amount || 0);
  const formatted = num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (lang === 'bn') {
    return formatBanglaNumber(formatted);
  }
  return formatted;
}

function formatNumber(num, user) {
  if (!user) user = getCurrentUser();
  const lang = getActiveLang(user);
  const n = Number(num || 0);
  const formatted = n.toLocaleString('en-US');
  if (lang === 'bn') {
    return formatBanglaNumber(formatted);
  }
  return formatted;
}

function getActiveLang(user) {
  if (!user) user = getCurrentUser();
  return normalizeAppLang((window.aloI18n ? window.aloI18n.getLanguage() : '') || (user && user.language) || localStorage.getItem('alo_lang') || 'en');
}

function getVipTierLabel(tierKey, lang) {
  const l = normalizeAppLang(lang || getActiveLang());
  if (typeof getActiveSalaryPageConfig === 'function') {
    const cfg = getActiveSalaryPageConfig();
    const matched = (cfg && Array.isArray(cfg.tiers)) ? cfg.tiers.find(function(t) { return t && t.id === tierKey; }) : null;
    if (matched) {
      return tLang(l, matched.nameBn, matched.nameEn, matched.nameAr);
    }
  }
  if (l === 'bn') return tierKey;
  const bnToNum = { '১': 1, '২': 2, '৩': 3, '৪': 4, '৫': 5, '৬': 6, '৭': 7, '৮': 8 };
  const m = String(tierKey || '').match(/([১-৮\d]+)/);
  const num = m ? (bnToNum[m[1]] || m[1]) : tierKey;
  return l === 'ar' ? ('المركز ' + num) : ('Position ' + num);
}

function getLv0TrialStatus(user) {
  if (!user) user = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
  const lvl = String((user && user.packageLevel) || 'LV0').toUpperCase().trim();
  const hasPaidPkg = lvl !== 'LV0' || (user && Array.isArray(user.purchasedPackages) && user.purchasedPackages.some(function(p) {
    const up = String(p || '').toUpperCase().trim();
    return Boolean(up && up !== 'LV0' && /^LV[1-9]\d*$/.test(up));
  }));
  const validityDays = Math.max(1, parseInt((packageData.LV0 && packageData.LV0.validityDays) || 5, 10) || 5);
  const dailyQuota = Math.max(1, parseInt((packageData.LV0 && packageData.LV0.count) || (packageTaskSettings.LV0 && packageTaskSettings.LV0.count) || 5, 10) || 5);
  const totalAllowedTasks = dailyQuota * validityDays;

  if (!user) {
    return {
      isLv0Only: false,
      isExpired: false,
      validityDays: validityDays,
      daysLeft: validityDays,
      dailyQuota: dailyQuota,
      totalAllowedTasks: totalAllowedTasks,
      finishedTasks: 0,
      remainingTasks: totalAllowedTasks,
      remainingAcceptableTasks: totalAllowedTasks
    };
  }

  let userMissions = [];
  try {
    const curU = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
    const targetPhone = normalizeBdPhone((user && (user.phone || user.accountNumber)) || '');
    const curPhone = normalizeBdPhone((curU && (curU.phone || curU.accountNumber)) || '');
    if (targetPhone && targetPhone === curPhone && typeof readAcceptedMissions === 'function') {
      userMissions = readAcceptedMissions();
    } else if (Array.isArray(user.acceptedMissions)) {
      userMissions = user.acceptedMissions;
    }
  } catch (e) {
    userMissions = Array.isArray(user.acceptedMissions) ? user.acceptedMissions : [];
  }

  let completedInList = 0;
  let reviewInList = 0;
  let activeInList = 0;
  userMissions.forEach(function(m) {
    if (!m) return;
    const mLvl = String(m.level || 'LV0').toUpperCase().trim();
    if (mLvl !== 'LV0') return;
    if (m.status === 'complete') completedInList += 1;
    else if (m.status === 'review') reviewInList += 1;
    else if (m.status === 'active') activeInList += 1;
  });

  const persistedCompleted = Number(user.lv0CompletedTasks) || 0;
  const totalCompleted = Math.max(completedInList, persistedCompleted);
  // LV0 expires strictly after finishing validityDays days of tasks (dailyQuota * validityDays), without 24h registration clock expiry
  const finishedTasks = totalCompleted + reviewInList;
  const totalInUseTasks = finishedTasks + activeInList;
  const isExpired = finishedTasks >= totalAllowedTasks;
  const remainingTasks = Math.max(0, totalAllowedTasks - finishedTasks);
  const remainingAcceptableTasks = Math.max(0, totalAllowedTasks - totalInUseTasks);
  const daysLeft = isExpired ? 0 : Math.max(1, Math.ceil(remainingTasks / dailyQuota));

  return {
    isLv0Only: !hasPaidPkg,
    isExpired: isExpired,
    validityDays: validityDays,
    daysLeft: daysLeft,
    dailyQuota: dailyQuota,
    totalAllowedTasks: totalAllowedTasks,
    finishedTasks: finishedTasks,
    remainingTasks: remainingTasks,
    remainingAcceptableTasks: remainingAcceptableTasks
  };
}
window.getLv0TrialStatus = getLv0TrialStatus;

function getPackageValidityStatus(level, user) {
  if (!user) user = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
  const lvl = String(level || 'LV0').toUpperCase().trim();
  const pkg = packageData[lvl];
  const validityDays = Math.max(1, parseInt((pkg && pkg.validityDays) || (lvl === 'LV0' ? 5 : 30), 10) || (lvl === 'LV0' ? 5 : 30));

  if (lvl === 'LV0') {
    const trial = getLv0TrialStatus(user);
    return {
      level: 'LV0',
      isOwned: true,
      isExpired: Boolean(trial.isExpired),
      isActive: !trial.isExpired,
      validityDays: trial.validityDays,
      daysLeft: trial.daysLeft
    };
  }

  if (!user) {
    return { level: lvl, isOwned: false, isExpired: false, isActive: false, validityDays: validityDays, daysLeft: 0 };
  }

  const userLevel = String(user.packageLevel || 'LV0').toUpperCase().trim();
  const purchasedList = Array.isArray(user.purchasedPackages)
    ? user.purchasedPackages.map(function(p) { return String(p || '').toUpperCase().trim(); })
    : [];
  const isOwned = (userLevel === lvl) || purchasedList.includes(lvl);
  if (!isOwned) {
    return { level: lvl, isOwned: false, isExpired: false, isActive: false, validityDays: validityDays, daysLeft: 0 };
  }

  const dates = (user.packagePurchaseDates && typeof user.packagePurchaseDates === 'object') ? user.packagePurchaseDates : {};
  const rawStart = dates[lvl] || user.updatedAt || user.updated_at || user.createdAt || user.created_at;
  const startTs = rawStart ? new Date(rawStart).getTime() : NaN;
  if (!Number.isFinite(startTs) || startTs <= 0) {
    return { level: lvl, isOwned: true, isExpired: false, isActive: true, validityDays: validityDays, daysLeft: validityDays };
  }

  const totalMs = validityDays * 24 * 60 * 60 * 1000;
  const elapsedMs = Math.max(0, Date.now() - startTs);
  const remainingMs = totalMs - elapsedMs;
  const isExpired = remainingMs <= 0;
  const daysLeft = isExpired ? 0 : Math.max(1, Math.ceil(remainingMs / (24 * 60 * 60 * 1000)));
  return {
    level: lvl,
    isOwned: true,
    isExpired: isExpired,
    isActive: !isExpired,
    validityDays: validityDays,
    daysLeft: daysLeft
  };
}
window.getPackageValidityStatus = getPackageValidityStatus;

function isLevelUnlocked(targetLevel, user) {
  if (!user) user = getCurrentUser();
  const lvl = String(targetLevel || 'LV0').toUpperCase().trim();
  if (lvl === 'LV0') {
    const trialStatus = getLv0TrialStatus(user);
    return !trialStatus.isExpired;
  }
  if (!user) return false;
  const targetStatus = getPackageValidityStatus(lvl, user);
  if (targetStatus.isOwned) {
    return !targetStatus.isExpired;
  }
  const userLevel = String(user.packageLevel || 'LV0').toUpperCase().trim();
  const userIdx = LEVEL_ORDER.indexOf(userLevel);
  const targetIdx = LEVEL_ORDER.indexOf(lvl);
  if (userIdx >= targetIdx && userIdx > 0) {
    const activeStatus = getPackageValidityStatus(userLevel, user);
    return !activeStatus.isExpired;
  }
  return false;
}

let currentPurchaseLevel = 'LV1';
let pendingPurchaseLevel = '';
