function syncLv0ExpiredStamp(cardEl, shouldShow) {
  if (!cardEl) return;
  const existing = cardEl.querySelector('.lv0-expired-stamp-overlay');
  if (shouldShow) {
    if (!existing) {
      const overlay = document.createElement('div');
      overlay.className = 'lv0-expired-stamp-overlay';
      overlay.setAttribute('aria-hidden', 'true');
      const img = document.createElement('img');
      img.src = '/assets/aistudio/images__1__b17277ca.jpeg';
      img.alt = 'EXPIRED';
      img.className = 'lv0-expired-stamp-img';
      img.draggable = false;
      overlay.appendChild(img);
      cardEl.appendChild(overlay);
    }
  } else if (existing) {
    existing.remove();
  }
}

function syncVipOwnedSeal(cardEl, shouldShow) {
  if (!cardEl) return;
  const existing = cardEl.querySelector('.vip-owned-seal-wrap');
  if (shouldShow) {
    if (!existing) {
      const wrap = document.createElement('div');
      wrap.className = 'vip-owned-seal-wrap';
      wrap.setAttribute('aria-hidden', 'true');
      const img = document.createElement('img');
      img.src = '/assets/aistudio/maxresdefault_2cef91ca.jpg';
      img.alt = 'CONGRATULATIONS';
      img.className = 'vip-owned-seal-img';
      img.draggable = false;
      wrap.appendChild(img);
      cardEl.appendChild(wrap);
    }
  } else if (existing) {
    existing.remove();
  }
}

function updateVipHallRooms() {
  const user = getCurrentUser();
  const userLevel = (user && user.packageLevel) || 'LV0';
  const rooms = document.querySelectorAll('.hall-level-room');
  rooms.forEach(function(room) {
    const lvl = room.dataset.level;
    if (!lvl) return;
    const isCurrent = (lvl === userLevel);
    const pkgStatus = getPackageValidityStatus(lvl, user);
    const isRoomExpired = Boolean(pkgStatus.isOwned && pkgStatus.isExpired);

    const lang = getActiveLang(user);
    const hallLabels = {
      current: tLang(lang, 'বর্তমান স্তর', 'Current Tier', 'المستوى الحالي'),
      dailyWork: tLang(lang, 'দৈনন্দিন কর্ম:', 'Daily Tasks:', 'المهام اليومية:')
    };

    const pkg = packageData[lvl];
    const titleP = room.querySelector('p:not(.hall-daily-work)');
    if (titleP) {
      titleP.textContent = getPackageName(lvl, lang) || lvl;
    }
    const workP = room.querySelector('.hall-daily-work') || room.querySelector('p:last-of-type');
    if (workP && pkg) {
      workP.innerHTML = `${hallLabels.dailyWork} <strong class="ml-0.5 font-normal">${pkg.count}</strong>`;
    }

    let tag = room.querySelector('.hall-current-tag, .hall-status-tag');
    if (isCurrent && !isRoomExpired) {
      if (!tag) {
        tag = document.createElement('span');
        room.insertBefore(tag, room.firstChild);
      }
      tag.className = 'hall-current-tag';
      tag.textContent = hallLabels.current;
      tag.style.background = '';
      tag.style.color = '';
    } else if (tag) {
      tag.remove();
    }

    syncLv0ExpiredStamp(room, isRoomExpired);
  });
}

function formatValidityLabel(days, lang) {
  const d = Math.max(1, parseInt(days, 10) || 1);
  if (lang === 'bn') {
    return `মেয়াদ: ${formatBanglaNumber(d)} দিন`;
  }
  if (lang === 'ar') {
    return `الصلاحية: ${d} ${d >= 3 && d <= 10 ? 'أيام' : 'يوماً'}`;
  }
  return `Validity: ${d} ${d === 1 ? 'Day' : 'Days'}`;
}

function updateRecordsPanelPackages() {
  const user = getCurrentUser();
  const isUsd = isUsdOnlyUser(user);
  const userLevel = (user && user.packageLevel) || 'LV0';
  const curr = getUserCurrency(user);
  const sym = getUserCurrencySymbol(user);
  const lang = getActiveLang(user);

  const curLevelDisplay = document.getElementById('records-current-level-display');
  if (curLevelDisplay) {
    const pkgName = getPackageName(userLevel, lang);
    curLevelDisplay.textContent = pkgName || userLevel;
  }
  if (typeof reconcileUserFrozenBuckets === 'function' && user) {
    reconcileUserFrozenBuckets(user);
  }
  const balDisplay = document.getElementById('records-balance-display');
  if (balDisplay) {
    const pkgSpendableBal = Number((Number((user && user.balance) || 0) + Number((user && user.rechargeFrozenBalance) || 0)).toFixed(2));
    balDisplay.textContent = formatMoney(pkgSpendableBal, user);
  }

  const labels = {
    dailyTasks: tLang(lang, 'দৈনিক কাজ', 'Daily Tasks', 'المهام اليومية'),
    perTask: tLang(lang, 'প্রতি কাজ', 'Per Task', 'لكل مهمة'),
    validTime: tLang(lang, 'মেয়াদ', 'Valid Time', 'الصلاحية'),
    dailyIncome: tLang(lang, 'দৈনিক আয়', 'Daily Income', 'الدخل اليومي'),
    btnCurrent: tLang(lang, 'বর্তমান স্তর', 'Current Tier', 'المستوى الحالي'),
    btnPurchased: tLang(lang, 'ক্রয় করা হয়েছে ✓', 'Purchased ✓', 'تم الشراء ✓'),
    btnBuy: tLang(lang, 'আনলক করুন', 'Unlock now', 'فتح الآن'),
    freeText: tLang(lang, 'ফ্রি', 'Free', 'مجاني'),
    tasksUnit: lang === 'bn' ? 'টি' : ''
  };

  const formatDurationOnly = function(days, activeLang) {
    const d = Math.max(1, parseInt(days, 10) || 1);
    if (activeLang === 'bn') return `${formatBanglaNumber(d)} দিন`;
    if (activeLang === 'ar') return `${d} ${d >= 3 && d <= 10 ? 'أيام' : 'يوماً'}`;
    return `${d} ${d === 1 ? 'Day' : 'Days'}`;
  };

  const pkgCards = document.querySelectorAll('[data-record-package]');
  pkgCards.forEach(function(card) {
    const level = card.dataset.recordPackage;
    const pkg = packageData[level];
    if (!pkg) return;
    const pkgName = getPackageName(level, lang);
    const pkgPrice = isUsd ? getPackagePriceUsd(level) : Number(pkg.price || 0);
    const pkgReward = isUsd ? getPackageRewardUsd(level) : Number(pkg.reward || 0);
    const pkgDaily = Number((pkgReward * pkg.count).toFixed(2));
    const validityDays = Math.max(1, parseInt(pkg.validityDays, 10) || (level === 'LV0' ? 5 : 30));
    const pkgStatus = getPackageValidityStatus(level, user);
    const isExpiredCard = Boolean(pkgStatus.isOwned && pkgStatus.isExpired);

    // 1. Update Card Title (LV0 - LV6)
    const titleEl = card.querySelector('.vip-card-title');
    if (titleEl) {
      titleEl.textContent = pkgName || level;
    }

    // 2. Update Labels
    const lblTasks = card.querySelector('.vip-label-tasks');
    const lblPerTask = card.querySelector('.vip-label-pertask');
    const lblValidity = card.querySelector('.vip-label-validity');
    const lblIncome = card.querySelector('.vip-label-income');
    if (lblTasks) lblTasks.textContent = labels.dailyTasks;
    if (lblPerTask) lblPerTask.textContent = labels.perTask;
    if (lblValidity) lblValidity.textContent = labels.validTime;
    if (lblIncome) lblIncome.textContent = labels.dailyIncome;

    // 3. Update Values (Tasks, Per Task, Validity, Daily Income)
    const valTasks = card.querySelector('.vip-val-tasks');
    const valPerTask = card.querySelector('.vip-val-pertask');
    const valIncome = card.querySelector('.vip-val-income');
    const validityTextEl = card.querySelector('.package-validity-text');

    if (valTasks) {
      valTasks.textContent = `${formatNumber(pkg.count, user)}${labels.tasksUnit}`;
    }
    if (valPerTask) {
      valPerTask.textContent = isUsd ? `${sym}${formatMoney(pkgReward, user)} ${curr}` : `${formatMoney(pkgReward, user)} ${curr}`;
    }
    if (validityTextEl) {
      validityTextEl.textContent = formatDurationOnly(validityDays, lang);
    }
    if (valIncome) {
      valIncome.textContent = isUsd ? `${sym}${formatMoney(pkgDaily, user)} ${curr}` : `${formatMoney(pkgDaily, user)} ${curr}`;
    }

    // 4. Update Centered CTA Button (Price + Action matching layout)
    const priceLabel = pkgPrice === 0
      ? (isUsd ? `$0.00 ${labels.freeText}` : `${formatNumber(0, user)} ${labels.freeText}`)
      : (isUsd ? `${sym}${formatMoney(pkgPrice, user)} ${curr}` : `${formatNumber(pkgPrice, user)} ${curr}`);

    const isCurrent = (level === userLevel);
    const isPurchased = Boolean(user && user.purchasedPackages && user.purchasedPackages.includes(level));
    const btn = card.querySelector('[data-buy-package]');
    if (btn) {
      if (isExpiredCard && level === 'LV0') {
        btn.textContent = 'EXPIRED';
        btn.disabled = true;
        btn.className = 'package-card-btn vip-card-cta vip-card-cta--current';
      } else if (isExpiredCard) {
        btn.textContent = `EXPIRED · ${priceLabel}`;
        btn.disabled = false;
        btn.className = 'package-card-btn vip-card-cta vip-card-cta--buy';
      } else if (isCurrent) {
        btn.textContent = `${priceLabel} · ${labels.btnCurrent}`;
        btn.disabled = true;
        btn.className = 'package-card-btn vip-card-cta vip-card-cta--current';
      } else if (isPurchased) {
        btn.textContent = labels.btnPurchased;
        btn.disabled = true;
        btn.className = 'package-card-btn vip-card-cta vip-card-cta--purchased';
      } else {
        btn.textContent = `${priceLabel} · ${labels.btnBuy}`;
        btn.disabled = false;
        btn.className = 'package-card-btn vip-card-cta vip-card-cta--buy';
      }
    }

    // 5. Overlay clean EXPIRED stamp image whenever package validity has ended (LV0 - LV6)
    syncLv0ExpiredStamp(card, isExpiredCard);

    // 6. Overlay diagonal CONGRATULATIONS corner seal on the user's active/owned package (hidden when expired)
    syncVipOwnedSeal(card, (isCurrent || isPurchased) && !isExpiredCard);
  });
}

function switchSheetTab(tabName) {
  const purchaseTabBtn = document.getElementById('sheet-tab-purchase');
  const depositTabBtn = document.getElementById('sheet-tab-deposit');
  const purchaseView = document.getElementById('sheet-purchase-view');
  const depositView = document.getElementById('sheet-deposit-view');

  if (tabName === 'deposit') {
    if (depositTabBtn) {
      depositTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 bg-[#10b981] text-white shadow font-bold cursor-pointer';
    }
    if (purchaseTabBtn) {
      purchaseTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 text-slate-400 hover:text-white font-bold cursor-pointer';
    }
    if (depositView) depositView.classList.remove('hidden');
    if (purchaseView) purchaseView.classList.add('hidden');
  } else {
    if (purchaseTabBtn) {
      purchaseTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 bg-[#1264c9] text-white shadow font-bold cursor-pointer';
    }
    if (depositTabBtn) {
      depositTabBtn.className = 'py-2 rounded-lg transition-all flex items-center justify-center gap-1.5 text-slate-400 hover:text-white font-bold cursor-pointer';
    }
    if (purchaseView) purchaseView.classList.remove('hidden');
    if (depositView) depositView.classList.add('hidden');
  }
}

function openActionSheet() {
  const backdrop = document.getElementById('alo-action-backdrop');
  const sheet = document.getElementById('alo-action-sheet');
  if (backdrop) {
    backdrop.classList.add('is-active');
    backdrop.style.display = 'block';
  }
  if (sheet) {
    sheet.classList.add('is-active');
    sheet.style.display = 'flex';
  }
}

function closeActionSheet() {
  const backdrop = document.getElementById('alo-action-backdrop');
  const sheet = document.getElementById('alo-action-sheet');
  if (backdrop) {
    backdrop.classList.remove('is-active');
    setTimeout(function() {
      if (!backdrop.classList.contains('is-active')) {
        backdrop.style.display = 'none';
      }
    }, 320);
  }
  if (sheet) {
    sheet.classList.remove('is-active');
    setTimeout(function() {
      if (!sheet.classList.contains('is-active')) {
        sheet.style.display = 'none';
      }
    }, 380);
  }
}

document.addEventListener('keydown', function(event) {
  if (event.key === 'Escape') {
    closeActionSheet();
    closeManagerContactModal();
    closeCountryPickerModal();
    closePackageDetailsModal();
    if (typeof closeTeamMemberDetailModal === 'function') {
      closeTeamMemberDetailModal();
    }
  }
});

