// Package Purchase Handling: Real Supabase balance verification and persistence
function handlePackagePurchase(level, triggerBtn) {
  if (!packageData[level] || level === 'LV0') return;
  if (window.isProcessingPackagePurchase) return;

  const user = getCurrentUser();
  const initLang = getActiveLang(user);
  if (!user || (!user.phone && !user.accountNumber)) {
    showToastNotification(tLang(initLang, 'অনুগ্রহ করে প্রথমে লগইন করুন।', 'Please log in first.', 'يرجى تسجيل الدخول أولاً.'));
    if (typeof showView === 'function') showView('login');
    return;
  }

  const pkg = packageData[level];
  const pkgStatus = getPackageValidityStatus(level, user);
  const isExpiredOwned = Boolean(pkgStatus.isOwned && pkgStatus.isExpired);
  const isCurrent = (level === user.packageLevel) && !isExpiredOwned;
  const isPurchased = (user.purchasedPackages && user.purchasedPackages.includes(level)) && !isExpiredOwned;

  if (isCurrent) {
    showToastNotification(tLang(initLang, `আপনি বর্তমানে ${level} প্যাকেজে সক্রিয় রয়েছেন।`, `You are already active on the ${level} package.`, `أنت نشط بالفعل في باقة ${level}.`));
    return;
  }
  if (isPurchased) {
    showToastNotification(tLang(initLang, `এই প্যাকেজটি (${level}) আপনি ইতিমধ্যে ক্রয় করেছেন।`, `You have already purchased the ${level} package.`, `لقد اشتريت باقة ${level} بالفعل.`));
    return;
  }

  let btn = triggerBtn;
  if (!btn || !btn.isConnected) {
    btn = document.getElementById('page-pkg-buy-btn') || document.querySelector(`[data-buy-package="${level}"]`);
  }

  window.isProcessingPackagePurchase = true;

  let origHtml = '';
  let origClass = '';
  if (btn) {
    origHtml = btn.innerHTML;
    origClass = btn.className;
    btn.disabled = true;
    btn.innerHTML = `
      <span class="inline-flex items-center justify-center gap-2">
        <svg class="animate-spin h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
          <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z"></path>
        </svg>
        <span>${tLang(initLang, 'যাচাই করা হচ্ছে...', 'Verifying...', 'جاري التحقق...')}</span>
      </span>
    `;
    btn.className = 'px-8 py-3 rounded-xl bg-[#2bb4d4] text-[#030d24] font-black text-sm shadow-lg opacity-90 cursor-wait flex items-center justify-center gap-2';
  }

  setTimeout(async function() {
    try {
      let freshUser = getCurrentUser() || user;
      const phoneKey = freshUser.phone || freshUser.accountNumber;
      const liveDbUser = phoneKey ? await dbGetUser(phoneKey) : null;
      if (liveDbUser) {
        freshUser = Object.assign({}, freshUser, liveDbUser);
      }

      if (typeof reconcileUserFrozenBuckets === 'function') {
        reconcileUserFrozenBuckets(freshUser);
      }

      const isUsd = isUsdOnlyUser(freshUser);
      const lang = getActiveLang(freshUser);
      const userBal = Number(freshUser.balance || 0);
      const rechargeBal = Number(freshUser.rechargeFrozenBalance || 0);
      const spendableForPkg = Number((userBal + rechargeBal).toFixed(2));
      const price = isUsd ? getPackagePriceUsd(level) : Number(pkg.price || 0);

      if (spendableForPkg < price) {
        if (btn) {
          btn.disabled = true;
          btn.style.transition = 'all 0.5s ease-in-out';
          btn.style.opacity = '1';
          btn.className = 'px-6 py-3 rounded-xl bg-rose-600 text-white font-black text-sm shadow-lg shadow-rose-950/60 flex items-center justify-center gap-1.5 cursor-not-allowed transition-all duration-500';
          btn.innerHTML = `
            <span class="inline-flex items-center gap-1.5 transition-opacity duration-700 ease-in-out" id="insufficient-bal-label">
              <svg class="w-4 h-4 text-white shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/>
              </svg>
              <span>${tLang(lang, 'অপর্যাপ্ত ব্যালেন্স', 'Insufficient Balance', 'الرصيد غير كافٍ')}</span>
            </span>
          `;
        }

        setTimeout(function() {
          if (btn && btn.isConnected) {
            const label = btn.querySelector('#insufficient-bal-label');
            if (label) label.style.opacity = '0';
            btn.style.opacity = '0.4';

            setTimeout(function() {
              const checkUser = getCurrentUser();
              const checkStatus = checkUser ? getPackageValidityStatus(level, checkUser) : { isActive: false };
              if (!checkUser || !checkStatus.isActive) {
                btn.disabled = false;
                btn.className = origClass || 'px-8 py-3 rounded-xl bg-[#35c6e7] hover:bg-[#2bb4d4] text-[#030d24] font-black text-sm shadow-lg transition-all duration-500 active:scale-95 cursor-pointer';
                btn.innerHTML = origHtml || tLang(lang, 'ক্রয় করুন', 'Buy Now', 'اشترِ الآن');
                btn.style.opacity = '0';
                requestAnimationFrame(function() { btn.style.opacity = '1'; });
              }
            }, 650);
          }
        }, 3600);
        return;
      }

      // Sufficient package-purchasable balance (recharge frozen credit first, then available earnings)
      const usedFromRecharge = Math.min(rechargeBal, price);
      const usedFromAvail = Number((price - usedFromRecharge).toFixed(2));
      freshUser.rechargeFrozenBalance = Number(Math.max(0, rechargeBal - usedFromRecharge).toFixed(2));
      freshUser.balance = Number(Math.max(0, userBal - usedFromAvail).toFixed(2));
      freshUser.frozenBalance = Number(((Number(freshUser.frozenBalance) || 0) + usedFromAvail).toFixed(2));
      const prevActiveLevel = String(freshUser.packageLevel || 'LV0').toUpperCase().trim();
      const prevActiveStatus = getPackageValidityStatus(prevActiveLevel, freshUser);
      const prevIdx = LEVEL_ORDER.indexOf(prevActiveLevel);
      const nextIdx = LEVEL_ORDER.indexOf(level);
      if (!prevActiveStatus.isActive || nextIdx >= prevIdx) {
        freshUser.packageLevel = level;
      }
      if (!Array.isArray(freshUser.purchasedPackages)) freshUser.purchasedPackages = ['LV0'];
      if (!freshUser.purchasedPackages.includes(level)) {
        freshUser.purchasedPackages.push(level);
      }
      if (!freshUser.packagePurchaseDates || typeof freshUser.packagePurchaseDates !== 'object') {
        freshUser.packagePurchaseDates = {};
      }
      freshUser.packagePurchaseDates[level] = new Date().toISOString();

      localStorage.setItem('my_pass_available_bal', freshUser.balance.toFixed(2));
      localStorage.setItem('aloSignedInUser', JSON.stringify(freshUser));

      await dbSaveUser(freshUser);

      // Keep Supabase team table & local team cache level synced immediately on package purchase
      const purchasedPhoneNorm = normalizeBdPhone(freshUser.phone || freshUser.accountNumber);
      if (window.aloSupabase && purchasedPhoneNorm) {
        try {
          await window.aloSupabase
            .from('team')
            .update({ level: level })
            .in('member_phone', expandPhoneLookupKeys([purchasedPhoneNorm, freshUser.phone || freshUser.accountNumber]));
        } catch (e) {}
      }
      try {
        const localTeam = JSON.parse(localStorage.getItem('aloTeamRecords') || '[]');
        let changedTeamLocal = false;
        localTeam.forEach(function(item) {
          if (normalizeBdPhone(item.memberPhone) === purchasedPhoneNorm) {
            item.level = level;
            changedTeamLocal = true;
          }
        });
        if (changedTeamLocal) localStorage.setItem('aloTeamRecords', JSON.stringify(localTeam));
      } catch (e) {}

      const now = new Date();
      await dbRecordTransaction({
        phone: freshUser.phone || freshUser.accountNumber,
        type: 'package',
        amount: price,
        ratio: '100%',
        actual: price,
        status: 'অনুমোদিত',
        method: isUsd ? `Package Purchase (${level})` : `প্যাকেজ ক্রয় (${level})`,
        date: now.toISOString().split('T')[0],
        time: now.toTimeString().split(' ')[0],
        newBalance: freshUser.balance
      });

      // Distribute 3-level Package Purchase Referral Commission: Level 1 (6%), Level 2 (2%), Level 3 (1%)
      if (level !== 'LV0' && price > 0 && typeof distributeTeamCommission === 'function') {
        try {
          await distributeTeamCommission(freshUser.phone || freshUser.accountNumber, price, {
            kind: 'package',
            packageLevel: level,
            currency: getUserCurrency(freshUser)
          });
        } catch (commErr) {
          console.warn('[Commission] Package commission warning:', commErr);
        }
      }

      if (btn) {
        btn.textContent = tLang(lang, 'বর্তমান স্তর', 'Current Tier', 'المستوى الحالي');
        btn.disabled = true;
        btn.className = 'px-6 py-3 rounded-xl bg-slate-700/60 text-slate-400 font-bold text-sm cursor-default';
      }

      updateUserDetails(freshUser);
      updateProfileMetrics();
      updateVipHallRooms();
      updateRecordsPanelPackages();

      showToastNotification(tLang(
        lang,
        `🎉 অভিনন্দন! আপনার ${level} প্যাকেজ সফলভাবে সক্রিয় হয়েছে!`,
        `🎉 Congratulations! Your ${level} package has been activated!`,
        `🎉 تهانينا! تم تفعيل باقة ${level} بنجاح!`
      ));

      const detailPanel = document.getElementById('package-detail-panel');
      if (detailPanel && !detailPanel.hidden) {
        renderPackageDetailPage(level);
      }
    } finally {
      window.isProcessingPackagePurchase = false;
    }
  }, 500);
}

