// Referral Commission Rates:
// - Package Purchase: Level 1 = 6%, Level 2 = 2%, Level 3 = 1%
// - Daily Task Earnings: Level 1 = 3%, Level 2 = 2%, Level 3 = 1%
const PACKAGE_COMMISSION_RATES = { 1: 0.06, 2: 0.02, 3: 0.01 };
const DAILY_TASK_COMMISSION_RATES = { 1: 0.03, 2: 0.02, 3: 0.01 };

// Update member's recharge_amount totals in team table (without crediting referral commission on raw deposit)
async function updateTeamRechargeStats(memberPhone, rechargeAmount) {
  const normPhone = normalizeBdPhone(memberPhone);
  const amt = Number(rechargeAmount) || 0;
  if (amt <= 0 || !normPhone) return;

  try {
    const local = JSON.parse(localStorage.getItem('aloTeamRecords') || '[]');
    local.forEach(function(r) {
      if (normalizeBdPhone(r.memberPhone) === normPhone) {
        r.rechargeAmount = Number(((Number(r.rechargeAmount) || 0) + amt).toFixed(2));
      }
    });
    localStorage.setItem('aloTeamRecords', JSON.stringify(local));
  } catch (e) {}
}

// Distribute multi-level team commissions across Level 1, Level 2, and Level 3:
// - kind = 'package': 6% (L1), 2% (L2), 1% (L3)
// - kind = 'task':    3% (L1), 2% (L2), 1% (L3)
async function distributeTeamCommission(memberPhone, baseAmount, options) {
  const opts = (options && typeof options === 'object') ? options : {};
  const kind = opts.kind === 'task' ? 'task' : 'package';
  const pkgLevel = opts.packageLevel ? String(opts.packageLevel).toUpperCase().trim() : '';
  const normPhone = normalizeBdPhone(memberPhone);
  const amt = Number(baseAmount) || 0;
  if (amt <= 0 || !normPhone) return;

  const rateTable = kind === 'task' ? DAILY_TASK_COMMISSION_RATES : PACKAGE_COMMISSION_RATES;

  const lookupPhones = expandPhoneLookupKeys([normPhone, memberPhone]);

  // If package purchase, update member's level in Supabase team & local aloTeamRecords
  if (kind === 'package' && pkgLevel && pkgLevel !== 'LV0') {
    if (window.aloSupabase) {
      try {
        await window.aloSupabase
          .from('team')
          .update({ level: pkgLevel })
          .in('member_phone', lookupPhones.length > 0 ? lookupPhones : [normPhone]);
      } catch (e) {}
    }
    try {
      const local = JSON.parse(localStorage.getItem('aloTeamRecords') || '[]');
      local.forEach(function(r) {
        if (normalizeBdPhone(r.memberPhone) === normPhone) {
          r.level = pkgLevel;
        }
      });
      localStorage.setItem('aloTeamRecords', JSON.stringify(local));
    } catch (e) {}
  }

  let teamRows = [];
  if (window.aloSupabase) {
    try {
      const { data } = await window.aloSupabase
        .from('team')
        .select('*')
        .in('member_phone', lookupPhones.length > 0 ? lookupPhones : [normPhone]);
      if (data && data.length > 0) teamRows = data;
    } catch (e) {}
  }

  if (teamRows.length === 0) {
    try {
      const local = JSON.parse(localStorage.getItem('aloTeamRecords') || '[]');
      teamRows = local.filter(function(r) {
        return normalizeBdPhone(r.memberPhone) === normPhone;
      });
    } catch (e) {}
  }

  const memberProfile = await dbGetUser(normPhone).catch(function() { return null; });
  const healedMemberId = (memberProfile && memberProfile.memberId) ? memberProfile.memberId : '';
  const healedMemberLevel = pkgLevel || (memberProfile && memberProfile.packageLevel) || 'LV0';

  // Resolve Tier 1
  let upline1Phone = null;
  let upline1User = null;
  const t1Row = teamRows.find(r => Number(r.tier) === 1);
  if (t1Row) {
    const raw = t1Row.superior_phone || t1Row.superiorPhone;
    upline1User = await dbFindInviter(raw);
    upline1Phone = upline1User ? normalizeBdPhone(upline1User.phone || upline1User.accountNumber || upline1User.account_number) : normalizeBdPhone(raw);
  } else {
    const selfUser = memberProfile;
    const selfSup = (selfUser && selfUser.superiorPhone && selfUser.superiorPhone !== '11')
      ? selfUser.superiorPhone
      : (selfUser && selfUser.superiorId && selfUser.superiorId !== '11' ? selfUser.superiorId : null);
    if (selfSup) {
      upline1User = await dbFindInviter(selfSup);
      upline1Phone = upline1User ? normalizeBdPhone(upline1User.phone || upline1User.accountNumber || upline1User.account_number) : normalizeBdPhone(selfSup);
      if (upline1Phone && upline1Phone !== normPhone) {
        teamRows.push({
          superior_phone: upline1Phone,
          member_phone: normPhone,
          tier: 1
        });
        await dbAddTeamMember(upline1Phone, normPhone, healedMemberId, healedMemberLevel, 1).catch(function() {});
      }
    }
  }

  // Resolve Tier 2
  let upline2Phone = null;
  let upline2User = null;
  const t2Row = teamRows.find(r => Number(r.tier) === 2);
  if (t2Row) {
    const raw = t2Row.superior_phone || t2Row.superiorPhone;
    upline2User = await dbFindInviter(raw);
    upline2Phone = upline2User ? normalizeBdPhone(upline2User.phone || upline2User.accountNumber || upline2User.account_number) : normalizeBdPhone(raw);
  } else if (upline1Phone) {
    if (!upline1User) upline1User = await dbGetUser(upline1Phone);
    const sup2Target = (upline1User && upline1User.superiorPhone && upline1User.superiorPhone !== '11')
      ? upline1User.superiorPhone
      : ((upline1User && upline1User.superiorId && upline1User.superiorId !== '11') ? upline1User.superiorId : null);
    if (sup2Target) upline2User = await dbFindInviter(sup2Target);
    upline2Phone = upline2User ? normalizeBdPhone(upline2User.phone || upline2User.accountNumber || upline2User.account_number) : null;
    if (!upline2Phone) {
      upline2Phone = await dbFindDirectSuperiorPhone(upline1Phone);
      if (upline2Phone && !upline2User) upline2User = await dbFindInviter(upline2Phone);
    }
    if (upline2Phone && upline2Phone !== normPhone && upline2Phone !== upline1Phone) {
      teamRows.push({
        superior_phone: upline2Phone,
        member_phone: normPhone,
        tier: 2
      });
      await dbAddTeamMember(upline2Phone, normPhone, healedMemberId, healedMemberLevel, 2).catch(function() {});
    }
  }

  // Resolve Tier 3
  let upline3Phone = null;
  let upline3User = null;
  const t3Row = teamRows.find(r => Number(r.tier) === 3);
  if (t3Row) {
    const raw = t3Row.superior_phone || t3Row.superiorPhone;
    upline3User = await dbFindInviter(raw);
    upline3Phone = upline3User ? normalizeBdPhone(upline3User.phone || upline3User.accountNumber || upline3User.account_number) : normalizeBdPhone(raw);
  } else if (upline2Phone) {
    if (!upline2User) upline2User = await dbGetUser(upline2Phone);
    const sup3Target = (upline2User && upline2User.superiorPhone && upline2User.superiorPhone !== '11')
      ? upline2User.superiorPhone
      : ((upline2User && upline2User.superiorId && upline2User.superiorId !== '11') ? upline2User.superiorId : null);
    if (sup3Target) upline3User = await dbFindInviter(sup3Target);
    upline3Phone = upline3User ? normalizeBdPhone(upline3User.phone || upline3User.accountNumber || upline3User.account_number) : null;
    if (!upline3Phone) {
      upline3Phone = await dbFindDirectSuperiorPhone(upline2Phone);
      if (upline3Phone && !upline3User) upline3User = await dbFindInviter(upline3Phone);
    }
    if (upline3Phone && upline3Phone !== normPhone && upline3Phone !== upline1Phone && upline3Phone !== upline2Phone) {
      teamRows.push({
        superior_phone: upline3Phone,
        member_phone: normPhone,
        tier: 3
      });
      await dbAddTeamMember(upline3Phone, normPhone, healedMemberId, healedMemberLevel, 3).catch(function() {});
    }
  }

  const activeSelfProfile = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
  const activeSelfMatch = activeSelfProfile && normalizeBdPhone(activeSelfProfile.phone || activeSelfProfile.accountNumber) === normPhone;
  const memberCurr = opts.currency ||
    (memberProfile ? getUserCurrency(memberProfile) : (activeSelfMatch ? getUserCurrency(activeSelfProfile) : 'USD'));

  // Deduplicate by resolved superior phone & lowest tier (so multi-row team entries for same upline never double-credit)
  const tierSortedRows = teamRows.slice().sort(function(a, b) {
    return (Number(a.tier) || 1) - (Number(b.tier) || 1);
  });
  const creditedPhones = new Set();

  for (const rec of tierSortedRows) {
    const tier = Number(rec.tier) || 1;
    if (tier < 1 || tier > 3) continue;
    const rate = rateTable[tier] || 0;
    const supPhoneRaw = rec.superior_phone || rec.superiorPhone;

    if (supPhoneRaw && rate > 0) {
      let supPhone = normalizeBdPhone(supPhoneRaw);
      let supUser = supPhone ? await dbGetUser(supPhone) : null;
      if (!supUser && supPhoneRaw) {
        supUser = await dbFindInviter(supPhoneRaw);
        if (supUser) {
          supPhone = normalizeBdPhone(supUser.phone || supUser.accountNumber || supUser.account_number);
        }
      }

      if (supUser && supPhone && supPhone !== normPhone && !creditedPhones.has(supPhone)) {
        const supCurr = getUserCurrency(supUser);
        // Convert unrounded base amount into recipient currency and carry sub-cent fractional dust so USD/USDT daily task commissions never drop to $0.00
        const baseInSupCurrExact = convertBetweenCurrenciesExact(amt, memberCurr, supCurr);
        const rawComm = baseInSupCurrExact * rate;
        if (rawComm <= 0) continue;

        creditedPhones.add(supPhone);
        const prevDust = Number(supUser.commissionDust) || 0;
        const combined = rawComm + prevDust;
        const commission = Math.floor((combined + 1e-9) * 100) / 100;
        const nextDust = Number(Math.max(0, combined - commission).toFixed(6));
        supUser.commissionDust = nextDust;

        if (commission <= 0) {
          await dbSaveUser(supUser);
          const activeSignedInDust = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
          if (activeSignedInDust && normalizeBdPhone(activeSignedInDust.phone || activeSignedInDust.accountNumber) === supPhone) {
            activeSignedInDust.commissionDust = nextDust;
            localStorage.setItem('aloSignedInUser', JSON.stringify(activeSignedInDust));
          }
          continue;
        }

        supUser.balance = Number(((Number(supUser.balance) || 0) + commission).toFixed(2));
        supUser.totalIncome = Number(((Number(supUser.totalIncome) || 0) + commission).toFixed(2));
        supUser.lifetimeEarnings = Number(((Number(supUser.lifetimeEarnings) || 0) + commission).toFixed(2));
        const supLastUpd = supUser.updatedAt || (supUser._rawOpt && supUser._rawOpt.updated_at) || '';
        const sameDayAsUpdate = !supLastUpd || (new Date(supLastUpd).toDateString() === new Date().toDateString());
        supUser.todayIncome = Number((((sameDayAsUpdate ? Number(supUser.todayIncome) : 0) || 0) + commission).toFixed(2));
        await dbSaveUser(supUser);

        if (typeof _realTeamCache !== 'undefined') _realTeamCache.delete(supPhone);

        // If this superior is the currently logged-in user, update in-memory state & UI immediately
        const activeSignedInUser = typeof getCurrentUser === 'function' ? getCurrentUser() : null;
        if (activeSignedInUser && normalizeBdPhone(activeSignedInUser.phone || activeSignedInUser.accountNumber) === supPhone) {
          activeSignedInUser.balance = supUser.balance;
          activeSignedInUser.totalIncome = supUser.totalIncome;
          activeSignedInUser.lifetimeEarnings = supUser.lifetimeEarnings;
          activeSignedInUser.todayIncome = supUser.todayIncome;
          activeSignedInUser.commissionDust = supUser.commissionDust;
          localStorage.setItem('my_pass_available_bal', supUser.balance.toFixed(2));
          localStorage.setItem('aloSignedInUser', JSON.stringify(activeSignedInUser));
          if (typeof updateUserDetails === 'function') updateUserDetails(activeSignedInUser);
          if (typeof updateProfileMetrics === 'function') updateProfileMetrics();
        }

        const now = new Date();
        const dateStr = now.toISOString().split('T')[0];
        const hours = String(now.getHours()).padStart(2, '0');
        const mins = String(now.getMinutes()).padStart(2, '0');
        const methodLabel = kind === 'task'
          ? (supCurr === 'USD' ? `Daily Task Commission (Tier ${tier})` : `দৈনিক কাজের কমিশন (স্তর ${tier})`)
          : (supCurr === 'USD' ? `Package Referral Commission (${pkgLevel || 'VIP'} · Tier ${tier})` : `প্যাকেজ রেফার কমিশন (${pkgLevel || 'VIP'} · স্তর ${tier})`);

        await dbRecordTransaction({
          phone: supPhone,
          type: 'commission',
          amount: commission,
          ratio: `${(rate * 100).toFixed(0)}%`,
          actual: commission,
          status: 'অনুমোদিত',
          method: methodLabel,
          date: dateStr,
          time: `${hours}:${mins}`,
          newBalance: supUser.balance
        });
        console.log(`[Commission:${kind}] Tier ${tier} (${(rate * 100)}%) credited ${commission} ${supCurr} (dust=${nextDust}) to ${supPhone}`);
      }
    }
  }
}
window.distributeTeamCommission = distributeTeamCommission;
window.distributeTeamRebate = distributeTeamCommission;

let _isConfirmingDeposit = false;
async function confirmDeposit() {
  if (_isConfirmingDeposit) return;
  const user = getCurrentUser();
  const langPre = getActiveLang(user);
  if (!user || (!user.phone && !user.accountNumber)) {
    showToastNotification(tLang(langPre, 'অনুগ্রহ করে প্রথমে লগইন করুন।', 'Please log in first.', 'يرجى تسجيل الدخول أولاً.'));
    if (typeof showView === 'function') showView('login');
    return;
  }

  const inlineDrawer = document.getElementById('inline-recharge-drawer');
  const isInlineOpen = !!(inlineDrawer && !inlineDrawer.classList.contains('hidden'));
  const customInput = document.getElementById(isInlineOpen ? 'inline-custom-deposit-amount' : 'custom-deposit-amount')
    || document.getElementById('custom-deposit-amount');
  const statusMsg = document.getElementById(isInlineOpen ? 'inline-deposit-status-message' : 'deposit-status-message')
    || document.getElementById('deposit-status-message');
  const submitDepBtn = document.getElementById(isInlineOpen ? 'inline-confirm-deposit-btn' : 'confirm-deposit-btn');
  let amount = selectedDepositAmount;
  if (customInput && customInput.value && parseFloat(customInput.value) > 0) {
    amount = parseFloat(customInput.value);
  }
  if (!amount || amount <= 0) {
    if (statusMsg) {
      statusMsg.className = 'text-center font-bold text-xs text-amber-300';
      statusMsg.textContent = tLang(langPre, 'অনুগ্রহ করে রিচার্জের সঠিক পরিমাণ দিন।', 'Please enter a valid deposit amount.', 'يرجى إدخال مبلغ إيداع صحيح.');
    }
    return;
  }

  const minRcAmt = toUserCurrencyAmount(Number((window.aloPlatformConfig && window.aloPlatformConfig.minRecharge) || 126), user);
  const sym = getUserCurrencySymbol(user);
  const isUsd = isUsdOnlyUser(user);
  if (amount < minRcAmt) {
    if (statusMsg) {
      statusMsg.className = 'text-center font-bold text-xs text-amber-300';
      statusMsg.textContent = tLang(
        langPre,
        `সর্বনিম্ন রিচার্জের পরিমাণ ${sym}${minRcAmt}`,
        `Minimum deposit is ${sym}${isUsd ? minRcAmt.toFixed(2) : minRcAmt}`,
        `الحد الأدنى للإيداع هو ${sym}${isUsd ? minRcAmt.toFixed(2) : minRcAmt}`
      );
    }
    return;
  }

  _isConfirmingDeposit = true;
  if (submitDepBtn) submitDepBtn.disabled = true;
  try {
    const now = new Date();
    const dateStr = now.toISOString().split('T')[0];
    const hours = String(now.getHours()).padStart(2, '0');
    const mins = String(now.getMinutes()).padStart(2, '0');
    const orderId = 'DEP' + Date.now() + Math.floor(100 + Math.random() * 900);
    const depPhone = user.phone || user.accountNumber;
    const depMethod = 'USDT (BEP20)';

    if (typeof upsertLocalDepositOrder === 'function') {
      upsertLocalDepositOrder(depPhone, {
        orderId: orderId,
        type: 'deposit',
        amount: amount,
        ratio: '0%',
        actual: amount,
        status: 'মুলতবি (Pending)',
        method: depMethod,
        date: dateStr,
        time: `${hours}:${mins}`,
        createdAt: now.toISOString()
      });
    }

    await dbRecordTransaction({
      phone: depPhone,
      type: 'deposit',
      amount: amount,
      ratio: '0%',
      actual: amount,
      status: 'মুলতবি (Pending)',
      method: depMethod,
      order_id: orderId,
      date: dateStr,
      time: `${hours}:${mins}`,
      newBalance: user.balance || 0
    });
    if (typeof renderAccountChangeHistory === 'function') renderAccountChangeHistory();

    const curr = getUserCurrency(user);
    const lang = getActiveLang(user);

    if (statusMsg) {
      statusMsg.className = 'text-center font-bold text-xs text-amber-300';
      statusMsg.textContent = tLang(
        lang,
        `⏳ ${formatMoney(amount, user)} ${curr} রিচার্জ আবেদন জমা হয়েছে — অ্যাডমিন যাচাইয়ের পর ব্যালেন্সে যোগ হবে!`,
        `⏳ ${formatMoney(amount, user)} ${curr} deposit request submitted (awaiting Admin approval)`,
        `⏳ تم إرسال طلب إيداع ${formatMoney(amount, user)} ${curr} (بانتظار موافقة الإدارة)`
      );
    }

    setTimeout(function() {
      closeActionSheet();
      showToastNotification(
        tLang(
          lang,
          `⏳ ${formatMoney(amount, user)} ${curr} ডিপোজিট অনুরোধ জমা হয়েছে (যাচাই চলমান)।`,
          `⏳ ${formatMoney(amount, user)} ${curr} deposit submitted for Admin review.`,
          `⏳ تم إرسال طلب الإيداع ${formatMoney(amount, user)} ${curr} لمراجعة الإدارة.`
        )
      );
    }, 650);
  } finally {
    _isConfirmingDeposit = false;
    if (submitDepBtn) submitDepBtn.disabled = false;
  }
}

function showToastNotification(messageText) {
  let toast = document.getElementById('alo-toast-notification');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'alo-toast-notification';
    toast.className = 'fixed top-4 inset-x-4 mx-auto max-w-sm z-[10005] p-3.5 rounded-2xl bg-[#071b50]/95 border-2 border-[#35c6e7] text-white shadow-[0_10px_35px_rgba(7,27,80,0.9)] backdrop-blur-md text-xs leading-5 flex items-center gap-3 transition-all duration-300 transform -translate-y-16 opacity-0 pointer-events-none';
    document.body.appendChild(toast);
  }
  toast.innerHTML = `<span class="text-xl shrink-0">✨</span><span class="flex-1 font-semibold text-[#e9f2ff]">${messageText}</span>`;
  toast.classList.remove('-translate-y-16', 'opacity-0', 'pointer-events-none');
  toast.classList.add('translate-y-0', 'opacity-100');
  setTimeout(function() {
    toast.classList.remove('translate-y-0', 'opacity-100');
    toast.classList.add('-translate-y-16', 'opacity-0', 'pointer-events-none');
  }, 3800);
}

let centerTextNoticeTimer = null;
function showCenterTextNotice(messageText) {
  let wrapper = document.getElementById('alo-center-text-notice');
  if (!wrapper) {
    wrapper = document.createElement('div');
    wrapper.id = 'alo-center-text-notice';
    wrapper.className = 'fixed inset-0 z-[10008] flex items-center justify-center pointer-events-none px-4';
    const box = document.createElement('div');
    box.id = 'alo-center-text-notice-box';
    box.className = 'rounded-lg bg-[#050d24]/95 text-[#f3f4f6] px-6 py-3 text-[14.5px] font-medium text-center shadow-xl transition-all duration-200 ease-out opacity-0 scale-90';
    box.style.fontFamily = "'Hind Siliguri', system-ui, -apple-system, sans-serif";
    wrapper.appendChild(box);
    document.body.appendChild(wrapper);
  }
  const box = document.getElementById('alo-center-text-notice-box');
  if (!box) return;
  if (centerTextNoticeTimer) {
    clearTimeout(centerTextNoticeTimer);
    centerTextNoticeTimer = null;
  }
  box.textContent = messageText;
  box.classList.remove('opacity-100', 'scale-100');
  box.classList.add('opacity-0', 'scale-90');
  void box.offsetWidth;
  box.classList.remove('opacity-0', 'scale-90');
  box.classList.add('opacity-100', 'scale-100');
  centerTextNoticeTimer = setTimeout(function() {
    box.classList.remove('opacity-100', 'scale-100');
    box.classList.add('opacity-0', 'scale-90');
  }, 2000);
}

function showToast(messageText) {
  showToastNotification(messageText);
}
window.showToast = showToastNotification;

// ==========================================
// PAYMENT METHOD SYSTEM (Screenshots Match)
// ==========================================
let selectedPaymentMethod = 'usdt';
let previousDashboardPanel = 'my-pass';

// ==========================================
// WITHDRAWAL SYSTEM & METHOD SELECTION ("পছন্দ")
// ==========================================
function getWithdrawalHistoryCacheKey(phone) {
  const norm = typeof normalizeBdPhone === 'function' ? normalizeBdPhone(phone || '') : String(phone || '');
  return norm ? `withdrawal_history_records_${norm}` : 'withdrawal_history_records';
}

function getWithdrawalHistory() {
  try {
    const user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    const key = getWithdrawalHistoryCacheKey(user && (user.phone || user.accountNumber));
    const raw = localStorage.getItem(key);
    if (raw) {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed.filter(function(r) { return !r.type || r.type === 'withdraw'; }) : [];
    }
  } catch (e) {}
  return [];
}

function saveWithdrawalHistory(history) {
  try {
    const user = (typeof getCurrentUser === 'function') ? getCurrentUser() : null;
    const key = getWithdrawalHistoryCacheKey(user && (user.phone || user.accountNumber));
    const withdrawOnly = (Array.isArray(history) ? history : []).filter(function(r) { return !r.type || r.type === 'withdraw'; });
    localStorage.setItem(key, JSON.stringify(withdrawOnly));
  } catch (e) {}
}

function renderWithdrawalHistoryRows(container, emptyState, list) {
  const withdrawList = (Array.isArray(list) ? list : []).filter(function(r) { return !r.type || r.type === 'withdraw'; });
  if (withdrawList.length === 0) {
    container.innerHTML = '';
    container.classList.add('hidden');
    if (emptyState) {
      emptyState.classList.remove('hidden');
      emptyState.classList.add('flex');
    }
    return;
  }
  if (emptyState) {
    emptyState.classList.add('hidden');
    emptyState.classList.remove('flex');
  }
  container.classList.remove('hidden');
  const lang = getActiveLang();
  container.innerHTML = withdrawList.map(function(item) {
    const stStr = String(item.status || '');
    const stLower = stStr.toLowerCase();
    const isRejected = stLower.includes('বাতিল') || stLower.includes('reject') || stLower.includes('অসফল') || stLower.includes('fail');
    const isApproved = !isRejected && (stLower.includes('অনুমোদিত') || stLower.includes('সফল') || stLower.includes('approv') || stLower.includes('complet') || stLower.includes('স্থানান্তরিত'));
    const stColor = isRejected ? '#f87171' : (isApproved ? '#34d399' : '#f59e0b');
    const stDisplay = tLang(
      lang,
      stStr || 'মুলতবি (Pending)',
      isRejected ? 'Rejected' : (isApproved ? 'Approved' : 'Pending'),
      isRejected ? 'مرفوض' : (isApproved ? 'تمت الموافقة' : 'قيد الانتظار')
    );
    return `
      <div class="grid grid-cols-5 items-center py-3.5 px-2 text-center hover:bg-[#081a4b] transition">
        <div class="text-left pl-1 font-bold font-mono text-white text-[13px]">${item.amount}</div>
        <div class="font-bold text-[13px]" style="color: #2d79f8;">${item.ratio}</div>
        <div class="font-bold font-mono text-white text-[13px]">${item.actual}</div>
        <div class="font-bold text-xs" style="color: ${stColor};">${stDisplay}</div>
        <div class="text-[10.5px] text-slate-200 leading-tight font-mono">
          <div>${item.date}</div>
          <div class="mt-0.5 text-slate-400">${item.time}</div>
        </div>
      </div>
    `;
  }).join('');
}

function renderWithdrawalHistory() {
  const container = document.getElementById('my-pass-history-rows');
  const emptyState = document.getElementById('my-pass-empty-state');
  if (!container) return;

  const user = getCurrentUser();
  if (!user || (!user.phone && !user.accountNumber)) {
    renderWithdrawalHistoryRows(container, emptyState, []);
    return;
  }

  const cachedHistory = getWithdrawalHistory();
  renderWithdrawalHistoryRows(container, emptyState, cachedHistory);

  // Authoritative sync from Supabase transactions table (withdrawal records ONLY)
  dbGetTransactions(user.phone || user.accountNumber, 'withdraw').then(function(dbList) {
    if (!Array.isArray(dbList)) return;
    const mapped = dbList.filter(function(tx) {
      return !tx.type || tx.type === 'withdraw';
    }).map(function(tx) {
      return {
        id: tx.id,
        type: 'withdraw',
        amount: Number(tx.amount || 0).toFixed(2),
        ratio: tx.ratio || '50.0%',
        actual: Number(tx.actual || 0).toFixed(2),
        status: tx.status || 'মুলতবি (Pending)',
        date: tx.date || (tx.createdAt ? String(tx.createdAt).split('T')[0] : ''),
        time: tx.time || ''
      };
    });
    saveWithdrawalHistory(mapped);
    renderWithdrawalHistoryRows(container, emptyState, mapped);
  }).catch(function() {});
}

// ==========================================
// ACCOUNT CHANGE RECORD / RECHARGE HISTORY (অ্যাকাউন্ট পরিবর্তন রেকর্ড)
// - Shows pending immediately when order placed
// - Profit Sharing Ratio column (100.0% approved / 0.0% pending or failed)
// - Auto-approves if backend receives balance; fails after 10 minutes if unpaid
// ==========================================
const RECHARGE_PENDING_TIMEOUT_MS = 10 * 60 * 1000;
const _expiringDepositOrdersSet = new Set();

function getDepositCacheKey(phone) {
  const norm = typeof normalizeBdPhone === 'function' ? normalizeBdPhone(phone || '') : String(phone || '');
  return norm ? `alo_deposit_history_${norm}` : 'alo_deposit_history_guest';
}

function getLocalDepositOrders(phone) {
  try {
    const raw = localStorage.getItem(getDepositCacheKey(phone));
    if (raw) {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    }
  } catch (e) {}
  return [];
}

function saveLocalDepositOrders(phone, list) {
  try {
    const clean = (Array.isArray(list) ? list : []).slice(0, 500);
    localStorage.setItem(getDepositCacheKey(phone), JSON.stringify(clean));
  } catch (e) {}
}

function upsertLocalDepositOrder(phone, orderObj) {
  if (!phone || !orderObj) return;
  const list = getLocalDepositOrders(phone);
  const key = String(orderObj.orderId || orderObj.order_id || orderObj.id || '');
  const normalized = Object.assign({
    type: 'deposit',
    createdAt: orderObj.createdAt || orderObj.created_at || new Date().toISOString()
  }, orderObj, {
    orderId: orderObj.orderId || orderObj.order_id || ''
  });
  let replaced = false;
  const next = list.map(function(item) {
    const itemKey = String(item.orderId || item.order_id || item.id || '');
    if (key && itemKey && key === itemKey) {
      replaced = true;
      return Object.assign({}, item, normalized);
    }
    return item;
  });
  if (!replaced) {
    next.unshift(normalized);
  }
  saveLocalDepositOrders(phone, next);
}
window.upsertLocalDepositOrder = upsertLocalDepositOrder;

function parseDepositCreatedMs(tx) {
  const raw = tx.createdAt || tx.created_at;
  if (raw) {
    const parsed = Date.parse(raw);
    if (!isNaN(parsed)) return parsed;
  }
  if (tx.date) {
    const tPart = tx.time || '00:00:00';
    const parsed = Date.parse(`${tx.date}T${tPart}`);
    if (!isNaN(parsed)) return parsed;
  }
  return Date.now();
}

function getDepositStatusPriority(statusStr) {
  const s = String(statusStr || '').toLowerCase();
  if (s.includes('অসফল') || s.includes('বাতিল') || s.includes('fail') || s.includes('reject') || s.includes('expir')) return 2;
  if (s.includes('অনুমোদিত') || s.includes('সফল') || s.includes('approv') || s.includes('complet') || s.includes('success') || s.includes('গৃহীত')) return 3;
  return 1;
}

function formatMmSs(ms) {
  const totalSec = Math.max(0, Math.ceil(Number(ms || 0) / 1000));
  const m = String(Math.floor(totalSec / 60)).padStart(2, '0');
  const s = String(totalSec % 60).padStart(2, '0');
  return `${m}:${s}`;
}

function formatLocalDateAndTime(createdMs, fallbackDate, fallbackTime) {
  if (createdMs && !isNaN(createdMs)) {
    try {
      const d = new Date(createdMs);
      const yyyy = d.getFullYear();
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      const dd = String(d.getDate()).padStart(2, '0');
      const hh = String(d.getHours()).padStart(2, '0');
      const mi = String(d.getMinutes()).padStart(2, '0');
      return { dateStr: `${yyyy}-${mm}-${dd}`, timeStr: `${hh}:${mi}` };
    } catch (e) {}
  }
  const tRaw = String(fallbackTime || '');
  return {
    dateStr: String(fallbackDate || '').slice(0, 10) || '--',
    timeStr: tRaw.length >= 5 ? tRaw.slice(0, 5) : tRaw
  };
}

function normalizeAndDedupeDeposits(rawList, nowMs) {
  const map = new Map();
  const list = Array.isArray(rawList) ? rawList : [];
  for (let i = 0; i < list.length; i++) {
    const tx = list[i];
    if (!tx || (tx.type && tx.type !== 'deposit')) continue;
    const orderKey = String(tx.orderId || tx.order_id || tx.out_trade_no || tx.id || `row_${i}`);
    const existing = map.get(orderKey);
    const prio = getDepositStatusPriority(tx.status);
    if (!existing) {
      map.set(orderKey, tx);
    } else {
      const exPrio = getDepositStatusPriority(existing.status);
      if (prio > exPrio || (prio === exPrio && !existing.id && tx.id)) {
        map.set(orderKey, Object.assign({}, existing, tx));
      } else if (!existing.id && tx.id) {
        existing.id = tx.id;
      }
    }
  }

  const out = [];
  const newlyExpired = [];
  map.forEach(function(tx) {
    const createdMs = parseDepositCreatedMs(tx);
    const elapsed = nowMs - createdMs;
    const stLower = String(tx.status || '').toLowerCase();
    const isAlreadyFailed = stLower.includes('অসফল') || stLower.includes('বাতিল') || stLower.includes('fail') || stLower.includes('reject') || stLower.includes('expir');
    const amtNum = Number(tx.amount || 0);
    let actualNum = Number(tx.actual || 0);
    const hasPositiveAmount = amtNum > 0 || actualNum > 0;
    const isApproved = !isAlreadyFailed && hasPositiveAmount && (stLower.includes('অনুমোদিত') || stLower.includes('সফল') || stLower.includes('approv') || stLower.includes('complet') || stLower.includes('success') || stLower.includes('গৃহীত'));
    const isTimedOut = !isApproved && !isAlreadyFailed && elapsed >= RECHARGE_PENDING_TIMEOUT_MS;

    let state = 'pending';
    let remainingMs = Math.max(0, RECHARGE_PENDING_TIMEOUT_MS - elapsed);
    let statusText = tx.status || 'মুলতবি (Pending)';
    let ratioStr = '0.0%';

    if (isApproved) {
      state = 'approved';
      remainingMs = 0;
      ratioStr = '100.0%';
      if (actualNum <= 0) actualNum = amtNum;
    } else if (isAlreadyFailed || isTimedOut) {
      state = 'failed';
      remainingMs = 0;
      ratioStr = '0.0%';
      actualNum = 0;
      statusText = 'অসফল (Failed)';
      if (isTimedOut) {
        newlyExpired.push({
          id: tx.id,
          orderId: tx.orderId || tx.order_id || tx.out_trade_no || '',
          createdAt: tx.createdAt || tx.created_at || new Date(createdMs).toISOString()
        });
      }
    }

    const dt = formatLocalDateAndTime(createdMs, tx.date, tx.time);
    out.push({
      id: tx.id || '',
      orderId: tx.orderId || tx.order_id || tx.out_trade_no || '',
      type: 'deposit',
      method: tx.method || '',
      amount: amtNum,
      actual: actualNum,
      ratio: ratioStr,
      status: statusText,
      state: state,
      createdMs: createdMs,
      createdAt: tx.createdAt || tx.created_at || new Date(createdMs).toISOString(),
      remainingMs: remainingMs,
      date: dt.dateStr,
      time: dt.timeStr
    });
  });

  out.sort(function(a, b) { return b.createdMs - a.createdMs; });
  return { items: out, newlyExpired: newlyExpired };
}

async function expireTimedOutDepositsInSupabase(phone, newlyExpired) {
  if (!Array.isArray(newlyExpired) || newlyExpired.length === 0) return;
  const normPhone = normalizeBdPhone(phone || '');

  for (let i = 0; i < newlyExpired.length; i++) {
    const item = newlyExpired[i];
    const trackKey = String(item.orderId || item.id || item.createdAt || i);

    upsertLocalDepositOrder(normPhone, {
      id: item.id,
      orderId: item.orderId,
      status: 'অসফল (Failed)',
      ratio: '0%',
      actual: 0,
      createdAt: item.createdAt
    });

    if (_expiringDepositOrdersSet.has(trackKey) || !window.aloSupabase) continue;
    _expiringDepositOrdersSet.add(trackKey);

    try {
      const updatePayload = {
        status: 'অসফল (Failed)',
        ratio: '0%',
        actual: 0
      };
      if (item.id) {
        await window.aloSupabase
          .from('transactions')
          .update(updatePayload)
          .eq('id', item.id);
      } else if (item.orderId) {
        await window.aloSupabase
          .from('transactions')
          .update(updatePayload)
          .eq('phone', normPhone)
          .eq('type', 'deposit')
          .ilike('method', `%${item.orderId}%`);
      }
    } catch (e) {
      _expiringDepositOrdersSet.delete(trackKey);
    }
  }
}

function renderAccountChangeHistoryRows(container, emptyState, items) {
  if (!Array.isArray(items) || items.length === 0) {
    container.innerHTML = '';
    container.classList.add('hidden');
    if (emptyState) {
      emptyState.classList.remove('hidden');
      emptyState.classList.add('flex');
    }
    return;
  }
  if (emptyState) {
    emptyState.classList.add('hidden');
    emptyState.classList.remove('flex');
  }
  container.classList.remove('hidden');
  const lang = getActiveLang();

  container.innerHTML = items.map(function(item) {
    const isApproved = item.state === 'approved';
    const isFailed = item.state === 'failed';
    const amtText = Number(item.amount || 0).toFixed(2);
    const ratioText = isApproved ? '100.0%' : '0.0%';

    let arrivalHtml = '';
    let statusHtml = '';

    if (isApproved) {
      const successWord = tLang(lang, 'সফল', 'Success', 'ناجح');
      const approvedWord = tLang(lang, 'অনুমোদিত', 'Approved', 'تمت الموافقة');
      arrivalHtml = `
        <div class="font-bold text-xs text-emerald-400">${successWord}</div>
        <div class="text-[10.5px] font-mono text-slate-300 mt-0.5">${Number(item.actual || item.amount || 0).toFixed(2)}</div>
      `;
      statusHtml = `<div class="font-bold text-xs text-emerald-400">${approvedWord}</div>`;
    } else if (isFailed) {
      const failedWord = tLang(lang, 'অসফল', 'Failed', 'فشل');
      arrivalHtml = `<div class="font-bold text-xs text-rose-400">${failedWord}</div>`;
      statusHtml = `<div class="font-bold text-xs text-rose-400">${failedWord}</div>`;
    } else {
      const pendingWord = tLang(lang, 'মুলতবি', 'Pending', 'قيد الانتظار');
      arrivalHtml = `<div class="font-bold text-xs text-amber-400">${pendingWord}</div>`;
      statusHtml = `
        <div class="font-bold text-xs text-amber-400">${pendingWord}</div>
        <div class="text-[10px] font-mono text-amber-300/90 mt-0.5 ac-pending-countdown" data-created-ms="${item.createdMs}">${formatMmSs(item.remainingMs)}</div>
      `;
    }

    return `
      <div class="grid grid-cols-5 items-center py-3.5 px-2 text-center hover:bg-[#081a4b] transition">
        <div class="text-left pl-1 font-bold font-mono text-white text-[13px]">${amtText}</div>
        <div class="font-bold text-[13px]" style="color: #2d79f8;">${ratioText}</div>
        <div>${arrivalHtml}</div>
        <div>${statusHtml}</div>
        <div class="text-[10.5px] text-slate-200 leading-tight font-mono">
          <div>${item.date}</div>
          <div class="mt-0.5 text-slate-400">${item.time}</div>
        </div>
      </div>
    `;
  }).join('');
}

let _accountChangeSyncInFlight = false;
async function renderAccountChangeHistory(options = {}) {
  const container = document.getElementById('account-change-history-rows');
  const emptyState = document.getElementById('account-change-empty-state');
  if (!container) return;

  const user = getCurrentUser();
  if (!user || (!user.phone && !user.accountNumber)) {
    renderAccountChangeHistoryRows(container, emptyState, []);
    return;
  }

  const userPhone = user.phone || user.accountNumber;
  const nowMs = Date.now();
  const cachedRaw = getLocalDepositOrders(userPhone);
  const cachedNorm = normalizeAndDedupeDeposits(cachedRaw, nowMs);
  renderAccountChangeHistoryRows(container, emptyState, cachedNorm.items);
  if (cachedNorm.newlyExpired.length > 0) {
    expireTimedOutDepositsInSupabase(userPhone, cachedNorm.newlyExpired);
  }

  if (_accountChangeSyncInFlight) return;
  _accountChangeSyncInFlight = true;
  try {
    const dbList = await dbGetTransactions(userPhone, 'deposit');
    if (dbList === null) return;
    const latestNow = Date.now();
    const dbItems = Array.isArray(dbList) ? dbList : [];

    // Permanently preserve all local approved/failed/pending orders not yet returned by Supabase (never delete older records)
    const preservedLocalOnly = getLocalDepositOrders(userPhone).filter(function(loc) {
      const locKey = extractOrderIdFromTx(loc) || String(loc.id || '');
      if (!locKey) return false;
      const inDb = dbItems.some(function(d) {
        const dbKey = extractOrderIdFromTx(d) || String(d.id || '');
        return dbKey && dbKey === locKey;
      });
      return !inDb;
    });

    const combined = dbItems.concat(preservedLocalOnly);
    const normalized = normalizeAndDedupeDeposits(combined, latestNow);

    if (normalized.newlyExpired.length > 0) {
      await expireTimedOutDepositsInSupabase(userPhone, normalized.newlyExpired);
    }

    saveLocalDepositOrders(userPhone, normalized.items);
    renderAccountChangeHistoryRows(container, emptyState, normalized.items);

    const hasPendingUsdt = normalized.items.some(function(it) {
      return it.state === 'pending' && String(it.method || '').toLowerCase().includes('usdt');
    });
    if (options && options.checkBackend && hasPendingUsdt && typeof checkUserUsdtDepositBalance === 'function') {
      checkUserUsdtDepositBalance({ showToast: false });
    }
  } catch (e) {
    console.warn('renderAccountChangeHistory sync error:', e);
  } finally {
    _accountChangeSyncInFlight = false;
  }
}
window.renderAccountChangeHistory = renderAccountChangeHistory;

let _accountChangeCountdownInterval = null;
let _accountChangeBackendPollCounter = 0;

function stopAccountChangePolling() {
  if (_accountChangeCountdownInterval) {
    clearInterval(_accountChangeCountdownInterval);
    _accountChangeCountdownInterval = null;
  }
  _accountChangeBackendPollCounter = 0;
}

function startAccountChangePolling() {
  stopAccountChangePolling();
  _accountChangeCountdownInterval = setInterval(function() {
    const panel = document.getElementById('account-change-panel');
    if (!panel || panel.hidden) {
      stopAccountChangePolling();
      return;
    }

    const countdownEls = panel.querySelectorAll('.ac-pending-countdown');
    const nowMs = Date.now();
    let needsRefresh = false;

    countdownEls.forEach(function(el) {
      const createdMs = Number(el.getAttribute('data-created-ms') || 0);
      if (!createdMs) return;
      const rem = RECHARGE_PENDING_TIMEOUT_MS - (nowMs - createdMs);
      if (rem <= 0) {
        el.textContent = '00:00';
        needsRefresh = true;
      } else {
        el.textContent = formatMmSs(rem);
      }
    });

    _accountChangeBackendPollCounter += 1;
    if (needsRefresh || (countdownEls.length > 0 && _accountChangeBackendPollCounter % 3 === 0)) {
      renderAccountChangeHistory({ checkBackend: true });
    }
  }, 1000);
}
window.startAccountChangePolling = startAccountChangePolling;
window.stopAccountChangePolling = stopAccountChangePolling;

if (typeof window !== 'undefined' && !window._acFocusSyncBound) {
  window._acFocusSyncBound = true;
  document.addEventListener('visibilitychange', function() {
    if (document.visibilityState === 'visible') {
      const panel = document.getElementById('account-change-panel');
      if (panel && !panel.hidden && typeof renderAccountChangeHistory === 'function') {
        renderAccountChangeHistory({ checkBackend: true });
      }
    }
  });
}

