// Deterministic UUID generator for members
function generateMemberUuid(seedStr) {
  const seed = String(seedStr || 'member');
  let h = 0x811c9dc5;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  const hex1 = Math.abs(h).toString(16).padStart(8, '0').slice(0, 8);
  const hex2 = Math.abs(Math.imul(h, 31)).toString(16).padStart(4, '0').slice(0, 4);
  const hex3 = '4' + Math.abs(Math.imul(h, 47)).toString(16).padStart(3, '0').slice(0, 3);
  const hex4 = 'a' + Math.abs(Math.imul(h, 71)).toString(16).padStart(3, '0').slice(0, 3);
  const hex5 = (Math.abs(Math.imul(h, 103)).toString(16) + Math.abs(Math.imul(h, 151)).toString(16)).padStart(12, '9').slice(0, 12);
  return `${hex1}-${hex2}-${hex3}-${hex4}-${hex5}`.toUpperCase();
}

async function openTeamMemberDetailModal(phoneOrMember, tierNum, idx) {
  const modal = document.getElementById('team-member-detail-modal');
  if (!modal) return;

  let member = null;
  const targetPhone = typeof phoneOrMember === 'string' ? phoneOrMember : (phoneOrMember && (phoneOrMember.rawPhone || phoneOrMember.phone));
  const t = Number(tierNum) || 1;
  const itemIdx = Number(idx) || 0;

  if (cachedTeamReportData) {
    const list = cachedTeamReportData[`tier${t}`] || cachedTeamReportData.all || [];
    member = list.find(function(m) { return (m.rawPhone === targetPhone || m.phone === targetPhone); }) || list[itemIdx] || null;
  }

  if (!member && typeof phoneOrMember === 'object' && phoneOrMember !== null) {
    member = phoneOrMember;
  }

  const rawPhone = targetPhone || (member && (member.rawPhone || member.phone)) || '';
  const maskedPhone = maskTeamPhone(rawPhone);
  const normP = normalizeBdPhone(rawPhone);

  let memberAcc = normP ? await dbGetUser(normP).catch(function() { return null; }) : null;

  const memberId = (memberAcc && memberAcc.memberId) || (member && member.memberId) || (normP ? normP.slice(-6) : '—');

  // Account / Registered Phone Number
  const regNumber = rawPhone || (memberAcc && (memberAcc.phone || memberAcc.accountNumber)) || '';
  const maskedAccNumber = maskAccountPhone3(regNumber);

  // Tier and Account Number
  const tierEl = document.getElementById('team-modal-tier');
  const uuidEl = document.getElementById('team-modal-uuid');
  const nameEl = document.getElementById('team-modal-name');
  if (tierEl) tierEl.textContent = `L${t}`;
  if (uuidEl) uuidEl.textContent = `ID:${memberId}`;
  if (nameEl) nameEl.textContent = maskedAccNumber || maskedPhone;

  // Avatar
  const avatarEl = document.getElementById('team-modal-avatar');
  if (avatarEl) {
    avatarEl.src = '/assets/rabbit_avatar-DZmseAUF.jpg';
    avatarEl.onerror = function() { this.src = '/team_avatar.png'; };
  }

  if (memberAcc) {
    member = Object.assign({}, member || {}, {
      balance: memberAcc.balance,
      rechargeAmount: memberAcc.rechargeAmount,
      cashoutAmount: memberAcc.cashoutAmount,
      level: memberAcc.packageLevel,
      inviteCode: memberAcc.inviteCode,
      memberId: memberAcc.memberId
    });
  }

  // Real Financial Data from Supabase user row (converted to viewer's active currency)
  const viewerUser = getCurrentUser();
  const viewerIsUsd = isUsdOnlyUser(viewerUser);
  const viewerSym = getUserCurrencySymbol(viewerUser);
  const viewerCurr = getUserCurrency(viewerUser);
  const viewerLang = getActiveLang(viewerUser);
  const memberCurr = (memberAcc && memberAcc.currency) || (member && member.currency) || 'USD';

  const rawBalance = Number((memberAcc && memberAcc.balance) ?? (member && member.balance) ?? 0);
  let rawDeposit = Number((memberAcc && memberAcc.rechargeAmount) ?? (member && member.rechargeAmount) ?? 0);

  // Also sum approved deposits from Supabase transactions for accuracy
  const txLookupPhones = expandPhoneLookupKeys([rawPhone, normP]);
  if (window.aloSupabase && txLookupPhones.length > 0) {
    try {
      const { data: depList, error: depErr } = await window.aloSupabase
        .from('transactions')
        .select('amount, actual, status')
        .in('phone', txLookupPhones)
        .eq('type', 'deposit');
      if (!depErr && Array.isArray(depList)) {
        const approvedDepSum = depList.reduce(function(sum, r) {
          const st = String(r.status || '').toLowerCase();
          const isFail = st.includes('অসফল') || st.includes('বাতিল') || st.includes('fail') || st.includes('reject') || st.includes('expir');
          if (!isFail && (st.includes('অনুমোদিত') || st.includes('সফল') || st.includes('approv') || st.includes('complet') || st.includes('success'))) {
            const actualVal = Number(r.actual) || 0;
            return sum + (actualVal > 0 ? actualVal : (Number(r.amount) || 0));
          }
          return sum;
        }, 0);
        if (approvedDepSum > rawDeposit) rawDeposit = approvedDepSum;
      }
    } catch(e) {}
  }

  // Withdrawals calculation from Supabase transactions
  let rawWithdrawals = Number((memberAcc && memberAcc.cashoutAmount) ?? (member && member.cashoutAmount) ?? 0);
  if (window.aloSupabase && txLookupPhones.length > 0) {
    try {
      const { data: wList, error: wErr } = await window.aloSupabase
        .from('transactions')
        .select('amount, status')
        .in('phone', txLookupPhones)
        .eq('type', 'withdraw');
      if (!wErr && Array.isArray(wList)) {
        const dbW = wList.reduce(function(sum, r) {
          const st = String(r.status || '').toLowerCase();
          if (st.includes('বাতিল') || st.includes('reject')) return sum;
          return sum + (Number(r.amount) || 0);
        }, 0);
        if (dbW > rawWithdrawals) rawWithdrawals = dbW;
      }
    } catch(e) {}
  }

  const dispBalance = convertBetweenCurrencies(rawBalance, memberCurr, viewerCurr);
  const dispDeposit = convertBetweenCurrencies(rawDeposit, memberCurr, viewerCurr);
  const dispWithdrawals = convertBetweenCurrencies(rawWithdrawals, memberCurr, viewerCurr);

  const usdtBalance = (viewerIsUsd ? dispBalance : (dispBalance / 126)).toFixed(2);
  const usdtDeposit = (viewerIsUsd ? dispDeposit : (dispDeposit / 126)).toFixed(2);
  const usdtWithdrawals = (viewerIsUsd ? dispWithdrawals : (dispWithdrawals / 126)).toFixed(2);

  // Status Badge (active when Tier-1 member has purchased a paid LV1+ package)
  const statusEl = document.getElementById('team-modal-status-badge');
  const memberLvl = String((memberAcc && memberAcc.packageLevel) || (member && member.level) || 'LV0').toUpperCase().trim();
  const memberHasPaidPkg = (memberLvl !== 'LV0' && /^LV[1-9]\d*$/.test(memberLvl)) ||
    (memberAcc && Array.isArray(memberAcc.purchasedPackages) && memberAcc.purchasedPackages.some(function(p) {
      const up = String(p || '').toUpperCase().trim();
      return Boolean(up && up !== 'LV0' && /^LV[1-9]\d*$/.test(up));
    }));
  const isActive = isPaidActiveTeamMember({
    level: memberLvl,
    purchasedPackages: memberAcc ? memberAcc.purchasedPackages : [],
    hasPackageTx: memberHasPaidPkg,
    rechargeAmount: rawDeposit
  });
  if (statusEl) {
    if (isActive) {
      statusEl.className = 'inline-flex items-center text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
      statusEl.textContent = tLang(viewerLang, 'সক্রিয়', 'Active', 'نشط');
    } else {
      statusEl.className = 'inline-flex items-center text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-slate-800 text-slate-400';
      statusEl.textContent = tLang(viewerLang, 'নিষ্ক্রিয়', 'Inactive', 'غير نشط');
    }
  }

  // 1. Balance
  const balUsdtEl = document.getElementById('team-modal-balance-usdt');
  const balBdtEl = document.getElementById('team-modal-balance-bdt');
  if (balBdtEl) balBdtEl.textContent = `${viewerSym} ${dispBalance.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  if (balUsdtEl) balUsdtEl.textContent = `≈ ${usdtBalance} USDT`;

  // 2. Referral Friends Count from Supabase team/users
  let friendsCount = 0;
  if (window.aloSupabase && normP) {
    try {
      const supLookupPhones = expandPhoneLookupKeys([normP, rawPhone]);
      const { count: tCount } = await window.aloSupabase
        .from('team')
        .select('*', { count: 'exact', head: true })
        .in('superior_phone', supLookupPhones)
        .eq('tier', 1);
      if (typeof tCount === 'number') friendsCount = tCount;

      const supKeys = supLookupPhones.slice();
      if (memberAcc && memberAcc.inviteCode) supKeys.push(String(memberAcc.inviteCode));
      if (memberAcc && memberAcc.memberId) supKeys.push(String(memberAcc.memberId));
      const { count: uCount } = await window.aloSupabase
        .from('users')
        .select('*', { count: 'exact', head: true })
        .in('superior_id', supKeys);
      if (typeof uCount === 'number' && uCount > friendsCount) friendsCount = uCount;
    } catch(e) {}
  }

  const refValEl = document.getElementById('team-modal-referral-val');
  const refSubEl = document.getElementById('team-modal-referral-sub');
  if (refValEl) {
    refValEl.textContent = String(friendsCount);
    refValEl.className = 'text-xl sm:text-2xl font-black text-white font-[\'Hind_Siliguri\'] tracking-tight';
  }
  if (refSubEl) {
    refSubEl.textContent = tLang(viewerLang, 'জন', 'Users', 'مستخدمين');
  }

  // 3. Deposit
  const depUsdtEl = document.getElementById('team-modal-deposit-usdt');
  const depBdtEl = document.getElementById('team-modal-deposit-bdt');
  if (depBdtEl) depBdtEl.textContent = `${viewerSym} ${dispDeposit.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  if (depUsdtEl) depUsdtEl.textContent = `≈ ${usdtDeposit} USDT`;

  // 4. Withdrawals
  const withUsdtEl = document.getElementById('team-modal-withdraw-usdt');
  const withBdtEl = document.getElementById('team-modal-withdraw-bdt');
  if (withBdtEl) withBdtEl.textContent = `${viewerSym} ${dispWithdrawals.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  if (withUsdtEl) withUsdtEl.textContent = `≈ ${usdtWithdrawals} USDT`;

  modal.style.display = 'flex';
  modal.hidden = false;
}
