function handleLogout() {
  const l = getActiveLang();
  try {
    if (window.aloSupabase) {
      if (supabaseLiveChannel) {
        window.aloSupabase.removeChannel(supabaseLiveChannel);
        supabaseLiveChannel = null;
      }
      if (supabaseTxChannel) {
        window.aloSupabase.removeChannel(supabaseTxChannel);
        supabaseTxChannel = null;
      }
      if (supabaseConfigChannel) {
        window.aloSupabase.removeChannel(supabaseConfigChannel);
        supabaseConfigChannel = null;
      }
    }
  } catch (e) {}
  _liveSyncPhone = '';
  if (_liveUserDebounceTimer) clearTimeout(_liveUserDebounceTimer);
  if (_liveTxDebounceTimer) clearTimeout(_liveTxDebounceTimer);
  if (typeof _realTeamCache !== 'undefined') _realTeamCache.clear();
  cachedTeamReportData = null;
  cachedTeamCommissionTxs = null;
  clearUserCachesOnAuthSwitch();
  localStorage.removeItem('aloSignedInUser');
  showToastNotification(tLang(l, 'সফলভাবে সাইন আউট করা হয়েছে।', 'Signed out successfully.', 'تم تسجيل الخروج بنجاح.'));
  const loginPass = document.getElementById('login-password');
  if (loginPass) loginPass.value = '';
  showView('login');
}

const logoutBtn = document.getElementById('logout-button');
if (logoutBtn) {
  logoutBtn.addEventListener('click', handleLogout);
}


// PW Home Banner Carousel (3 Slides - Auto-change continually, Touch swipe OFF)
let pwBannerCurrentIndex = 0;
let pwBannerTimer = null;
const PW_BANNER_TOTAL = 4;

function ensureHomeBannerMediaReady() {
  const depositVideo = document.getElementById('pw-home-deposit-video');
  if (!depositVideo) return;

  depositVideo.muted = true;
  depositVideo.defaultMuted = true;
  depositVideo.playsInline = true;
  depositVideo.setAttribute('muted', '');
  depositVideo.setAttribute('playsinline', '');
  depositVideo.setAttribute('webkit-playsinline', 'true');

  if (!depositVideo.dataset.pwPlayBound) {
    depositVideo.dataset.pwPlayBound = 'true';
    const tryPlayOnReady = function() {
      const dash = document.getElementById('dashboard-view');
      const home = document.getElementById('home-panel');
      if (pwBannerCurrentIndex === 0 && dash && !dash.hidden && home && !home.hidden) {
        depositVideo.muted = true;
        const p = depositVideo.play();
        if (p && typeof p.catch === 'function') p.catch(function() {});
      }
    };
    depositVideo.addEventListener('loadeddata', tryPlayOnReady);
    depositVideo.addEventListener('canplay', tryPlayOnReady);
    document.addEventListener('visibilitychange', function() {
      if (!document.hidden) tryPlayOnReady();
    });
    const unlockOnce = function() {
      tryPlayOnReady();
      window.removeEventListener('touchstart', unlockOnce);
      window.removeEventListener('pointerdown', unlockOnce);
    };
    window.addEventListener('touchstart', unlockOnce, { passive: true });
    window.addEventListener('pointerdown', unlockOnce, { passive: true });
  }

  const dash = document.getElementById('dashboard-view');
  const home = document.getElementById('home-panel');
  if (pwBannerCurrentIndex === 0 && dash && !dash.hidden && home && !home.hidden) {
    if (depositVideo.readyState === 0) {
      try { depositVideo.load(); } catch (e) {}
    }
    const p = depositVideo.play();
    if (p && typeof p.catch === 'function') p.catch(function() {});
  }
}

function goToPWBannerSlide(idx) {
  pwBannerCurrentIndex = ((idx % PW_BANNER_TOTAL) + PW_BANNER_TOTAL) % PW_BANNER_TOTAL;
  const track = document.getElementById('pw-home-banner-track');
  if (track) {
    track.style.transition = 'transform 0.5s cubic-bezier(0.25, 1, 0.5, 1)';
    track.style.transform = `translateX(-${pwBannerCurrentIndex * (100 / PW_BANNER_TOTAL)}%)`;
  }
  document.querySelectorAll('.pw-banner-dot').forEach(function(dot, i) {
    if (i === pwBannerCurrentIndex) {
      dot.classList.add('is-active');
      dot.setAttribute('aria-current', 'true');
    } else {
      dot.classList.remove('is-active');
      dot.removeAttribute('aria-current');
    }
  });
  const depositVideo = document.getElementById('pw-home-deposit-video');
  if (depositVideo) {
    if (pwBannerCurrentIndex === 0) {
      ensureHomeBannerMediaReady();
    } else if (!depositVideo.paused) {
      depositVideo.pause();
    }
  }
  const holoSlide = document.getElementById('pw-home-holo-slide');
  if (holoSlide) {
    holoSlide.classList.toggle('pw-holo-paused', pwBannerCurrentIndex !== 1);
  }
  const teamSlide = document.getElementById('pw-home-team-slide');
  if (teamSlide) {
    teamSlide.classList.toggle('pw-holo-paused', pwBannerCurrentIndex !== 3);
  }
}

function startPWBannerAutoPlay() {
  stopPWBannerAutoPlay();
  // Automatically rotates every 3.8 seconds
  pwBannerTimer = setInterval(function() {
    goToPWBannerSlide(pwBannerCurrentIndex + 1);
  }, 3800);
}

function stopPWBannerAutoPlay() {
  if (pwBannerTimer) {
    clearInterval(pwBannerTimer);
    pwBannerTimer = null;
  }
}

function initPWBannerCarousel() {
  const container = document.getElementById('pw-hero-banner-container');
  const track = document.getElementById('pw-home-banner-track');
  if (!container || !track) return;

  goToPWBannerSlide(0);
  startPWBannerAutoPlay();

  // Navigation arrows (Touch swipe is OFF as requested by user)
  const prevBtn = document.getElementById('pw-banner-prev');
  const nextBtn = document.getElementById('pw-banner-next');
  if (prevBtn) {
    prevBtn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      goToPWBannerSlide(pwBannerCurrentIndex - 1);
      startPWBannerAutoPlay();
    });
  }
  if (nextBtn) {
    nextBtn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      goToPWBannerSlide(pwBannerCurrentIndex + 1);
      startPWBannerAutoPlay();
    });
  }

  // Block right-click / long-press save & drag on header banners, images, and videos
  if (!window._pwMediaProtectionBound) {
    window._pwMediaProtectionBound = true;
    document.addEventListener('contextmenu', function(e) {
      const t = e.target;
      if (!t) return;
      if (
        t.tagName === 'IMG' ||
        t.tagName === 'VIDEO' ||
        (t.closest && t.closest('#pw-hero-banner-container, .pw-media-shield, .home-cert-card, #home-cert-lightbox, #screenshot-lightbox-modal'))
      ) {
        e.preventDefault();
      }
    });
    document.addEventListener('dragstart', function(e) {
      const t = e.target;
      if (!t) return;
      if (
        t.tagName === 'IMG' ||
        t.tagName === 'VIDEO' ||
        (t.closest && t.closest('#pw-hero-banner-container, .home-cert-card'))
      ) {
        e.preventDefault();
      }
    });
  }
}

let _hydratingSessionPromise = null;
let _lastHydratedSessionAt = 0;

async function hydrateSessionFromSupabase(force) {
  const user = getCurrentUser();
  if (!user || (!user.phone && !user.accountNumber)) return;
  if (!window.aloSupabase) return;
  const now = Date.now();
  if (!force && _lastHydratedSessionAt > 0 && (now - _lastHydratedSessionAt) < 3000) return;
  if (_hydratingSessionPromise) return _hydratingSessionPromise;

  _hydratingSessionPromise = (async function() {
    try {
      const dbUser = await dbGetUser(user.phone || user.accountNumber);
      _lastHydratedSessionAt = Date.now();
      if (!dbUser) {
        // Account deleted in DB: sign out cleanly
        handleLogout();
        return;
      }

      if (dbUser.accountStatus === 'banned') {
        const l = getActiveLang(dbUser);
        clearUserCachesOnAuthSwitch();
        localStorage.removeItem('aloSignedInUser');
        showToastNotification(tLang(l, '⛔ আপনার অ্যাকাউন্টটি অ্যাডমিন কর্তৃক স্থগিত (Suspended) করা হয়েছে।', '⛔ Your account has been suspended by an administrator.', '⛔ تم تعليق حسابك من قبل المسؤول.'));
        showView('login');
        return;
      }

      const updated = Object.assign({}, user, dbUser);
      const localManual = localStorage.getItem('alo_lang_manual') === '1';
      if (localManual) {
        updated.language = normalizeAppLang(localStorage.getItem('alo_lang') || user.language || 'en');
        updated.languageManual = true;
      } else if (dbUser.languageManual) {
        updated.language = normalizeAppLang(dbUser.language || 'en');
        updated.languageManual = true;
      } else {
        updated.language = 'en';
        updated.languageManual = false;
      }
      hydrateUserCachesFromCloud(updated);
      localStorage.setItem('aloSignedInUser', JSON.stringify(updated));
      if (typeof setAppLanguage === 'function' && window.aloI18n && window.aloI18n.getLanguage() !== updated.language) {
        setAppLanguage(updated.language, { silent: !updated.languageManual });
      }

      updateUserDetails(updated);
      updateProfileMetrics();
      updateVipHallRooms();
      updateRecordsPanelPackages();
      updateBkashDisplayAcrossApp();
      updateNagadDisplayAcrossApp();
      updateUsdtDisplayAcrossApp();
      updateRealNameDisplayAcrossApp();
      updateFundPasswordDisplayAcrossApp();
      if (typeof renderWithdrawalHistory === 'function') renderWithdrawalHistory();
      if (typeof renderRecentUsdtDeposits === 'function') renderRecentUsdtDeposits();
      if (typeof renderSavingsPlanPanel === 'function') renderSavingsPlanPanel();
      if (typeof renderMissionRecords === 'function') renderMissionRecords(activeMissionFilter);
      if (typeof initSupabaseLiveSync === 'function') initSupabaseLiveSync(updated);
    } catch (e) {
      console.warn('Supabase session hydration notice:', e);
    } finally {
      _hydratingSessionPromise = null;
    }
  })();
  return _hydratingSessionPromise;
}
window.hydrateSessionFromSupabase = hydrateSessionFromSupabase;

